--liquibase formatted sql

-- English grammar lessons for English speakers: lesson texts that no longer compare Estonian with
-- Turkish, and an English podcast script per lesson (the podcast job turns each into audio).

--changeset english-grammar-content:a1 splitStatements:false
UPDATE grammar_lessons SET content = $c$<b>Personal Pronouns</b>

Every Estonian personal pronoun has a long and a short form. Short forms are the everyday default; long forms add emphasis or contrast.

<code>mina / ma</code> — I
<code>sina / sa</code> — you
<code>tema / ta</code> — he, she
<code>meie / me</code> — we
<code>teie / te</code> — you (plural or polite)
<code>nemad / nad</code> — they

💬 <i>Ma olen tudeng.</i> — I am a student.
💬 <i>Ta elab Tartus.</i> — She lives in Tartu.
💬 <i>Nad elavad Tallinnas.</i> — They live in Tallinn.
💬 <i>Kas te olete õpetaja?</i> — Are you a teacher? (polite)
💬 <i>Mina olen Ali, tema on Mari.</i> — I am Ali, and she is Mari.

⚠️ Do not use long forms all the time: <i>Mina olen tudeng</i> sounds like “I (not someone else) am a student”. In neutral speech say <i>Ma olen tudeng</i>. English “you” hides a choice: use <code>teie / te</code> for a group and to be polite to one person.

💡 <code>ta</code> means both he and she: Estonian pronouns have no gender, so context tells you who is meant.$c$ WHERE id = 'a1-personal-pronouns';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-personal-pronouns', 'en', $s$[{"text": "Hello. Today we are learning Estonian personal pronouns. They are the first words to learn, because you will hear them in almost every sentence.", "language": "en", "pause_after_ms": 1000}, {"text": "Every pronoun has a long form and a short form. I is <<mina>> or <<ma>>, you is <<sina>> or <<sa>>, and he or she is <<tema>> or <<ta>>.", "language": "en", "pause_after_ms": 1000}, {"text": "In the plural, we is <<meie>> or <<me>>, you is <<teie>> or <<te>>, and they is <<nemad>> or <<nad>>. In everyday speech, people use the short forms.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma olen tudeng.", "language": "et", "pause_after_ms": 2400}, {"text": "I am a student. Here we used the short form <<ma>>, which is the most natural choice.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta elab Tartus.", "language": "et", "pause_after_ms": 2400}, {"text": "She lives in Tartu. The word <<ta>> means both he and she, so Estonian never makes you choose.", "language": "en", "pause_after_ms": 1000}, {"text": "Nad elavad Tallinnas.", "language": "et", "pause_after_ms": 2400}, {"text": "They live in Tallinn. The short form is <<nad>>, and the long form is <<nemad>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Kas te olete õpetaja?", "language": "et", "pause_after_ms": 2400}, {"text": "Are you a teacher? English says you to everyone. Estonian uses <<te>> for a group, and also to speak politely to one person.", "language": "en", "pause_after_ms": 1000}, {"text": "Mina olen Ali, tema on Mari.", "language": "et", "pause_after_ms": 2400}, {"text": "I am Ali, and she is Mari. Here the long forms contrast two people and put stress on each one.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is to use the long forms everywhere. <<Mina>> adds emphasis. In normal speech, <<ma>> is enough.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. How do you say, she lives in Tallinn, with the short pronoun?", "language": "en", "pause_after_ms": 3800}, {"text": "Ta elab Tallinnas.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. First the short pronoun <<ta>>, then the verb <<elab>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, every pronoun has a long and a short form. Use the short form in everyday speech, and the long form for emphasis.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>The Verb olema (to be) — Present Tense</b>

<code>olema</code> links a person or thing to a job, a nationality, a feeling or a place. It works much like English “am / is / are”, and just like in English it cannot be left out.

<code>ma olen · sa oled · ta on</code>
<code>me oleme · te olete · nad on</code>
Negative for every person: <code>ei ole</code> (shorter: <code>pole</code>)

💬 <i>Ma olen õpetaja.</i> — I am a teacher.
💬 <i>Kas sa oled väsinud?</i> — Are you tired?
💬 <i>Ta on kodus.</i> — She is at home.
💬 <i>Me oleme Türgist.</i> — We are from Turkey.
💬 <i>Nad ei ole täna siin.</i> — They are not here today.

⚠️ Do not drop the verb, even in quick speech: <i>Ma õpetaja</i> is wrong, say <i>Ma olen õpetaja</i>. Also note there is no word for “a” or “the”.

💡 <code>ta</code> and <code>nad</code> share one form, <code>on</code>, and the negative never changes: <code>ei ole</code>.$c$ WHERE id = 'a1-olema-present';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-olema-present', 'en', $s$[{"text": "Hello. Today we are learning <<olema>>, the most important verb in Estonian. It means to be, and you use it to say who you are and where you are.", "language": "en", "pause_after_ms": 1000}, {"text": "Just like English am, is and are, this verb has to be there. You can never leave it out of the sentence.", "language": "en", "pause_after_ms": 1000}, {"text": "Here are the forms. <<ma olen>>, <<sa oled>>, <<ta on>>, <<me oleme>>, <<te olete>>, <<nad on>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma olen õpetaja.", "language": "et", "pause_after_ms": 2400}, {"text": "I am a teacher. The form <<olen>> does the job of English am. Notice there is no word for a.", "language": "en", "pause_after_ms": 1000}, {"text": "Kas sa oled väsinud?", "language": "et", "pause_after_ms": 2400}, {"text": "Are you tired? For you, the form is <<oled>>, and <<kas>> at the start makes it a question.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta on kodus.", "language": "et", "pause_after_ms": 2400}, {"text": "She is at home. The form for he or she is short and simple, <<on>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Me oleme Türgist.", "language": "et", "pause_after_ms": 2400}, {"text": "We are from Turkey. <<oleme>> is the form for we, and <<Türgist>> says where we come from.", "language": "en", "pause_after_ms": 1000}, {"text": "Nad ei ole täna siin.", "language": "et", "pause_after_ms": 2400}, {"text": "They are not here today. In the negative, every person uses the same pattern, <<ei ole>>. You can also say the shorter <<pole>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Never drop the verb, even in quick speech. Don't say <<ma õpetaja>>. Always say <<ma olen õpetaja>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. How do you say, we are at home, in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Me oleme kodus.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. <<oleme>> for we, and <<kodus>> for at home.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, <<olema>> is never dropped. For he, she and they the form is <<on>>, and the negative is always <<ei ole>>.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Nominative Case (nimetav)</b>

The nominative is the basic dictionary form of a noun. It answers <i>kes?</i> (who?) and <i>mis?</i> (what?) and is used for the subject and for the noun after <code>on</code> (is/are).

📌 Singular: no ending → <code>koer, raamat, maja</code>
📌 Plural: genitive + <code>-d</code> → <code>koera → koerad, raamatu → raamatud, maja → majad</code>

💬 <i>Koer on suur.</i> — The dog is big.
💬 <i>See on raamat.</i> — This is a book.
💬 <i>Õpetaja on klassis.</i> — The teacher is in the classroom.
💬 <i>Lapsed mängivad.</i> — The children are playing.
💬 <i>Minu sõber on eestlane.</i> — My friend is Estonian.

⚠️ After numbers from two upwards the noun is NOT nominative: <i>üks koer</i>, but <i>kaks koera</i>. English says “two dogs” with a plural, so <i>kaks koerad</i> is a classic slip.

💡 Learn every new noun with three forms: nominative, genitive, partitive — <code>koer – koera – koera</code>, <code>raamat – raamatu – raamatut</code>.$c$ WHERE id = 'a1-nominative-case';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-nominative-case', 'en', $s$[{"text": "Hello! Today we are learning the most basic Estonian case, the nominative, called <<nimetav>>. It is the form you see in the dictionary.", "language": "en", "pause_after_ms": 1000}, {"text": "The nominative has no ending. It is used for the subject of a sentence, and for the noun that comes after <<on>>, which means is.", "language": "en", "pause_after_ms": 1000}, {"text": "For the plural, add the sound <<d>> to the genitive form. For example, <<koer>> becomes <<koera>>, and the plural is <<koerad>>.", "language": "en", "pause_after_ms": 900}, {"text": "Koer on suur.", "language": "et", "pause_after_ms": 2400}, {"text": "The dog is big. <<Koer>> is the subject, and it has no ending.", "language": "en", "pause_after_ms": 900}, {"text": "See on raamat.", "language": "et", "pause_after_ms": 2400}, {"text": "This is a book. <<raamat>> comes after <<on>>, so it is in the nominative too. Estonian has no word for a or the.", "language": "en", "pause_after_ms": 1000}, {"text": "Õpetaja on klassis.", "language": "et", "pause_after_ms": 2400}, {"text": "The teacher is in the classroom. The subject here is <<õpetaja>>, the teacher.", "language": "en", "pause_after_ms": 900}, {"text": "Lapsed mängivad.", "language": "et", "pause_after_ms": 2400}, {"text": "The children are playing. <<Lapsed>> is the nominative plural. Listen for the <<d>> at the end.", "language": "en", "pause_after_ms": 900}, {"text": "Minu sõber on eestlane.", "language": "et", "pause_after_ms": 2400}, {"text": "My friend is Estonian. Both <<sõber>> and <<eestlane>> are in the nominative.", "language": "en", "pause_after_ms": 1000}, {"text": "Be careful. After the numbers two and up, the noun is not nominative. We say <<üks koer>>, but not <<kaks koer>>. The correct form is <<kaks koera>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say this in Estonian: This is a house.", "language": "en", "pause_after_ms": 3800}, {"text": "See on maja.", "language": "et", "pause_after_ms": 2400}, {"text": "That's the right answer. The word <<maja>> is in the nominative, with no ending.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up, the nominative is the dictionary form. It is used for the subject and for the noun after <<on>>. For the plural, add <<d>> to the genitive.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson!", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Numbers 1–10</b>
Numbers are everywhere: prices, phone numbers, the time. Learn the ten words, then one rule for the noun that follows them.

1 <code>üks</code> · 2 <code>kaks</code> · 3 <code>kolm</code> · 4 <code>neli</code> · 5 <code>viis</code>
6 <code>kuus</code> · 7 <code>seitse</code> · 8 <code>kaheksa</code> · 9 <code>üheksa</code> · 10 <code>kümme</code>

<code>üks</code> + nominative: <code>üks kass</code>
2–10 + partitive singular: <code>raamat → kaks raamatut</code>

💬 <i>Mul on üks kass.</i> — I have one cat.
💬 <i>Mul on kaks venda.</i> — I have two brothers.
💬 <i>Laual on kolm õuna.</i> — There are three apples on the table.
💬 <i>Toas on neli tooli.</i> — There are four chairs in the room.

⚠️ With most nouns, don't use the plural after a number: <i>kaks raamatut</i>, not <i>kaks raamatud</i>. English says “two books”, but in Estonian the noun stays singular and takes the partitive ending.
💡 Learn every new noun together with its partitive: <i>raamat – raamatut</i>, <i>õun – õuna</i>. Then counting is easy.$c$ WHERE id = 'a1-numbers';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-numbers', 'en', $s$[{"text": "Hello. Today we are learning the Estonian numbers from one to ten. You will meet them every day, when shopping, telling the time, or giving a phone number.", "language": "en", "pause_after_ms": 1000}, {"text": "First let's listen to the numbers. Then we'll see how to use them with nouns.", "language": "en", "pause_after_ms": 900}, {"text": "Üks, kaks, kolm, neli, viis.", "language": "et", "pause_after_ms": 2600}, {"text": "One, two, three, four, five. English has no sound like the ü in <<üks>>. Say ee, but round your lips as if for oo.", "language": "en", "pause_after_ms": 900}, {"text": "Kuus, seitse, kaheksa, üheksa, kümme.", "language": "et", "pause_after_ms": 2600}, {"text": "Six, seven, eight, nine, ten. <<Kaheksa>> means eight and <<üheksa>> means nine. They sound alike, so listen carefully.", "language": "en", "pause_after_ms": 1000}, {"text": "Now the rule. After <<üks>>, the noun stays in the nominative. After two and higher, the noun takes the partitive singular.", "language": "en", "pause_after_ms": 1100}, {"text": "Mul on üks kass.", "language": "et", "pause_after_ms": 2400}, {"text": "I have one cat. After <<üks>>, the word <<kass>> does not change at all.", "language": "en", "pause_after_ms": 900}, {"text": "Mul on kaks venda.", "language": "et", "pause_after_ms": 2400}, {"text": "I have two brothers. The word <<vend>> became <<venda>>. That's the partitive.", "language": "en", "pause_after_ms": 900}, {"text": "Laual on kolm õuna.", "language": "et", "pause_after_ms": 2400}, {"text": "There are three apples on the table. The word <<õun>> takes the form <<õuna>>.", "language": "en", "pause_after_ms": 900}, {"text": "Toas on neli tooli.", "language": "et", "pause_after_ms": 2400}, {"text": "There are four chairs in the room. The word <<tool>> becomes <<tooli>>, and it still stays singular.", "language": "en", "pause_after_ms": 900}, {"text": "A common mistake is to use the plural. In English we say two books, but in Estonian the noun stays singular and takes the partitive ending.", "language": "en", "pause_after_ms": 1100}, {"text": "Now you try. How do you say five books in Estonian? The word for book is <<raamat>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Viis raamatut.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. In the partitive, <<raamat>> became <<raamatut>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up, after <<üks>> use the nominative. After the numbers two to ten, use the partitive singular.", "language": "en", "pause_after_ms": 1000}, {"text": "Say the numbers out loud every day. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Question Words</b>

A question word goes at the start of the sentence. With a question word you do not use <code>kas</code>: it is only for yes/no questions.

<code>kes?</code> — who?
<code>mis?</code> — what?
<code>kus?</code> — where?
<code>kuhu?</code> — where to?
<code>kust?</code> — where from?
<code>millal?</code> — when?
<code>kuidas?</code> — how?
<code>miks?</code> — why?
<code>kui palju?</code> — how much?
<code>mitu?</code> — how many?

💬 <i>Kes see on?</i> — Who is this?
💬 <i>Kus sa elad?</i> — Where do you live?
💬 <i>Kuhu sa lähed?</i> — Where are you going?
💬 <i>Kuidas sul läheb?</i> — How are you?
💬 <i>Kui palju see maksab?</i> — How much does this cost?

⚠️ As in English, the question word comes first, but there is no helper like “do”: <i>Kus sa elad?</i>, not <i>Sa kus elad?</i>. Use <code>kas</code> only in yes/no questions.

💡 <code>kus · kuhu · kust</code> = <i>where · where to · where from</i>: place, direction, origin. English often says just “where”; Estonian always picks one of the three.$c$ WHERE id = 'a1-question-words';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-question-words', 'en', $s$[{"text": "Hello. Today we are learning Estonian question words. You need them to get to know people, ask the way, or ask a price.", "language": "en", "pause_after_ms": 1000}, {"text": "The question word goes at the start of the sentence. In these questions you do not use <<kas>>, because the question word already makes it a question.", "language": "en", "pause_after_ms": 1000}, {"text": "Kes see on?", "language": "et", "pause_after_ms": 2400}, {"text": "Who is this? <<Kes>> is used for people and means who.", "language": "en", "pause_after_ms": 1000}, {"text": "Mis see on?", "language": "et", "pause_after_ms": 2400}, {"text": "What is this? <<Mis>> is used for things and means what.", "language": "en", "pause_after_ms": 1000}, {"text": "Kus sa elad?", "language": "et", "pause_after_ms": 2400}, {"text": "Where do you live? <<Kus>> asks about location. Notice there is no extra word like English do.", "language": "en", "pause_after_ms": 1000}, {"text": "Kuhu sa lähed?", "language": "et", "pause_after_ms": 2400}, {"text": "Where are you going? <<Kuhu>> asks about direction, so it means where to.", "language": "en", "pause_after_ms": 1000}, {"text": "Kust sa pärit oled?", "language": "et", "pause_after_ms": 2400}, {"text": "Where are you from? <<Kust>> means where from. English often uses just where, but Estonian always picks one of these three words.", "language": "en", "pause_after_ms": 1000}, {"text": "Kuidas sul läheb?", "language": "et", "pause_after_ms": 2400}, {"text": "How are you? <<Kuidas>> means how, and this is one of the most common greetings.", "language": "en", "pause_after_ms": 1000}, {"text": "Kui palju see maksab?", "language": "et", "pause_after_ms": 2400}, {"text": "How much is this? <<Kui palju>> asks about amount and price. Also, <<millal>> means when, and <<miks>> means why.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is to keep the subject first, as in a statement. We don't say <<sa kus elad>>. We say <<kus sa elad>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. How do you ask, when are you coming, in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Millal sa tuled?", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The question word <<millal>> comes first, followed by <<sa tuled>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, the question word comes at the start of the sentence. And <<kas>> is only used in yes or no questions.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Basic Word Order: Subject – Verb – Object</b>

In a neutral Estonian sentence the subject comes first, the verb second and the object after the verb, just like in English.

<code>subject + verb + object</code>
<code>Ma + söön + leiba</code>
For a yes/no question, put <code>kas</code> at the start and keep the same order.

💬 <i>Ma söön leiba.</i> — I eat bread.
💬 <i>Ta loeb raamatut.</i> — She is reading a book.
💬 <i>Me õpime eesti keelt.</i> — We are learning Estonian.
💬 <i>Mari joob kohvi.</i> — Mari drinks coffee.
💬 <i>Kas sa räägid eesti keelt?</i> — Do you speak Estonian?

⚠️ Keep the verb in the middle: say <i>Ma söön leiba</i>; <i>Ma leiba söön</i> sounds marked or emphatic. And questions need no helper like English “do”: <code>kas</code> plus the normal order is enough.

💡 Think “who – does – what”. The verb is the second element of the sentence, even when something else comes first: <i>Täna söön ma leiba.</i> — Today I eat bread.$c$ WHERE id = 'a1-basic-word-order';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-basic-word-order', 'en', $s$[{"text": "Hello. Today we are learning basic Estonian word order. The right order helps people understand your first sentences straight away.", "language": "en", "pause_after_ms": 1000}, {"text": "In a neutral Estonian sentence, the subject comes first, then the verb, and then the object. Good news: that is the same order as in English.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma söön leiba.", "language": "et", "pause_after_ms": 2400}, {"text": "I eat bread. The subject is <<ma>>, the verb is <<söön>>, and the object is <<leiba>>. The verb comes right after the subject.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta loeb raamatut.", "language": "et", "pause_after_ms": 2400}, {"text": "She is reading a book. Same order. First the person, then the verb <<loeb>>, and the book at the end.", "language": "en", "pause_after_ms": 1000}, {"text": "Me õpime eesti keelt.", "language": "et", "pause_after_ms": 2400}, {"text": "We are learning Estonian. The verb <<õpime>> is in second place, and <<eesti keelt>> comes after the verb.", "language": "en", "pause_after_ms": 1000}, {"text": "Mari joob kohvi.", "language": "et", "pause_after_ms": 2400}, {"text": "Mari drinks coffee. When the subject is a name or a noun, the order stays the same.", "language": "en", "pause_after_ms": 1000}, {"text": "Kas sa räägid eesti keelt?", "language": "et", "pause_after_ms": 2400}, {"text": "Do you speak Estonian? For a yes or no question, put <<kas>> at the start. Everything else stays the same, with no helper like English do.", "language": "en", "pause_after_ms": 1000}, {"text": "One tip for English speakers. The verb likes second place. If you start with <<täna>>, meaning today, say <<täna söön ma leiba>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. How do you say, I drink coffee, in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Ma joon kohvi.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. First <<ma>>, then the verb <<joon>>, and <<kohvi>> at the end.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, the basic Estonian order is subject, verb, object. In a yes or no question, add <<kas>> at the start.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Negation with ei</b>

To make a present-tense verb negative, put <code>ei</code> before it and drop the personal ending. The negative form is the same for every person.

<code>ma söön → ma ei söö</code>
<code>ta räägib → ta ei räägi</code>
<code>nad tulevad → nad ei tule</code>
<code>ma olen → ma ei ole</code> (shorter: <code>ma pole</code>)

💬 <i>Ma ei söö liha.</i> — I don't eat meat.
💬 <i>Ta ei räägi eesti keelt.</i> — He doesn't speak Estonian.
💬 <i>Me ei ela Tallinnas.</i> — We don't live in Tallinn.
💬 <i>Nad ei tule täna.</i> — They are not coming today.
💬 <i>Ma ei ole väsinud.</i> — I am not tired.

⚠️ Never keep the ending after <code>ei</code>: <i>ma ei söön</i> ✗, <i>nad ei elavad</i> ✗.

💡 English switches between “don't” and “doesn't”; Estonian <code>ei</code> never changes. Take the “I” form and drop <code>-n</code>: <code>ma loen → ma ei loe</code>.$c$ WHERE id = 'a1-negation';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-negation', 'en', $s$[{"text": "Hello. Today we are learning how to make negative sentences in Estonian. The good news is that the rule is very regular, and the same for every person.", "language": "en", "pause_after_ms": 1000}, {"text": "Put <<ei>> before the verb, and the verb loses its personal ending. So <<ma söön>> becomes <<ma ei söö>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ei söö liha.", "language": "et", "pause_after_ms": 2400}, {"text": "I don't eat meat. The ending <<n>> from <<söön>> is gone, and <<söö>> is left.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta ei räägi eesti keelt.", "language": "et", "pause_after_ms": 2400}, {"text": "He doesn't speak Estonian. The positive form is <<räägib>>. In the negative, the ending <<b>> drops.", "language": "en", "pause_after_ms": 1000}, {"text": "Me ei ela Tallinnas.", "language": "et", "pause_after_ms": 2400}, {"text": "We don't live in Tallinn. For we, the verb is the same too, <<ei ela>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Nad ei tule täna.", "language": "et", "pause_after_ms": 2400}, {"text": "They are not coming today. Even in the plural there is no <<vad>> ending, just <<ei tule>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ei ole väsinud.", "language": "et", "pause_after_ms": 2400}, {"text": "I am not tired. The rule is the same for <<olema>>, so you say <<ei ole>>. You can also say the shorter <<ma pole>>.", "language": "en", "pause_after_ms": 1000}, {"text": "The most common mistake is to keep the ending. <<Ma ei söön>> and <<nad ei elavad>> are wrong. The ending always drops.", "language": "en", "pause_after_ms": 1000}, {"text": "English switches between don't and doesn't. In Estonian, <<ei>> is a separate word in front of the verb, and it never changes.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Make the sentence <<ma loen raamatut>> negative.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma ei loe raamatut.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The ending <<n>> dropped from <<loen>>, and it became <<ei loe>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, a negative sentence uses <<ei>> plus the verb without its ending. This form is the same for every person.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-present-tense', 'en', $s$[{"text": "Hello. Today we are learning present tense verb endings in Estonian. Once you know the six personal endings, you can use lots of verbs with ease.", "language": "en", "pause_after_ms": 1000}, {"text": "Estonian has only one present tense. <<Ma elan>> means both I live and I am living.", "language": "en", "pause_after_ms": 1000}, {"text": "The personal endings are <<n>>, <<d>>, <<b>>, <<me>>, <<te>> and <<vad>>. They are added to the verb stem.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma elan Tallinnas.", "language": "et", "pause_after_ms": 2400}, {"text": "I live in Tallinn. The stem of <<elama>> is <<ela>>, and for I we add <<n>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Sa elad Tartus.", "language": "et", "pause_after_ms": 2400}, {"text": "You live in Tartu. For you, the ending is <<d>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta töötab koolis.", "language": "et", "pause_after_ms": 2400}, {"text": "She works at a school. For he or she, the ending is <<b>>, and the verb is <<töötama>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Me räägime eesti keelt.", "language": "et", "pause_after_ms": 2400}, {"text": "We speak Estonian. For we, the ending is <<me>>. Here the stem of <<rääkima>> takes the form <<räägi>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Te loete raamatut.", "language": "et", "pause_after_ms": 2400}, {"text": "You are reading a book. For you, plural or polite, the ending is <<te>>. Here the stem of <<lugema>> takes the form <<loe>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Nad elavad Pärnus.", "language": "et", "pause_after_ms": 2400}, {"text": "They live in <<Pärnu>>. For they, the ending is <<vad>>.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is to use the ending <<b>> for they as well. <<Nad elab>> is wrong. The correct form is <<nad elavad>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To find the stem, learn the I form of each verb. Take <<ma loen>>, drop the ending <<n>>, and the stem <<loe>> is left.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. How do you say, they speak Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Nad räägivad eesti keelt.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The stem is <<räägi>>, and the ending for they is <<vad>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, add <<n>>, <<d>>, <<b>>, <<me>>, <<te>> or <<vad>> to the verb stem. This one form covers both English present tenses.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Possessive Constructions (mul on)</b>

Everyday Estonian does not use a verb for "to have" (the formal <i>omama</i> is rare). Instead it says "at me is": the owner takes the adessive ending <code>-l</code>, followed by <code>on</code>.

📌 <code>mul on</code> — I have
<code>sul on</code> — you have
<code>tal on</code> — he/she has
<code>meil on</code> — we have
<code>teil on</code> — you (plural/formal) have
<code>neil on</code> — they have
<code>õpetaja → õpetajal on</code> — the teacher has
Negative: <code>mul ei ole</code> + partitive: <code>auto → autot</code>

💬 <i>Mul on raamat.</i> — I have a book.
💬 <i>Tal on kaks last.</i> — She has two children.
💬 <i>Kas sul on aega?</i> — Do you have time?
💬 <i>Meil on uus korter.</i> — We have a new flat.
💬 <i>Mul ei ole autot.</i> — I don't have a car.

⚠️ Do not use <code>olema</code> with the owner as subject: <i>Ma olen auto</i> means "I am a car". In the negative use the partitive: <i>autot</i>, not <i>auto</i>.

💡 Read it word for word: <i>mul</i> = "at me", <i>on</i> = "is", <i>ei ole</i> = "is not". So <i>Mul on raamat</i> is "at me is a book".$c$ WHERE id = 'a1-possessive';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-possessive', 'en', $s$[{"text": "Hello! Today we are learning how to say that you have something in Estonian. You will use this pattern all the time in everyday speech.", "language": "en", "pause_after_ms": 1000}, {"text": "Everyday Estonian has no verb for to have. Instead, it says something like, at me is. The owner takes the ending <<l>>, followed by <<on>>.", "language": "en", "pause_after_ms": 1000}, {"text": "The forms are <<mul>>, <<sul>>, <<tal>>, <<meil>>, <<teil>>, <<neil>>. That is, I have, you have, he or she has, we have, you have, and they have.", "language": "en", "pause_after_ms": 1000}, {"text": "Mul on raamat.", "language": "et", "pause_after_ms": 2400}, {"text": "I have a book. Word for word, it means, at me is a book.", "language": "en", "pause_after_ms": 900}, {"text": "Tal on kaks last.", "language": "et", "pause_after_ms": 2400}, {"text": "She has two children. After a number, the word <<laps>> becomes <<last>>.", "language": "en", "pause_after_ms": 900}, {"text": "Kas sul on aega?", "language": "et", "pause_after_ms": 2400}, {"text": "Do you have time? To ask a question, put <<kas>> at the start of the sentence.", "language": "en", "pause_after_ms": 900}, {"text": "Meil on uus korter.", "language": "et", "pause_after_ms": 2400}, {"text": "We have a new flat. <<Meil on>> means we have.", "language": "en", "pause_after_ms": 900}, {"text": "Õpetajal on punane auto.", "language": "et", "pause_after_ms": 2400}, {"text": "The teacher has a red car. Nouns take the ending <<l>> too, <<õpetajal>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Careful. In the negative, <<on>> becomes <<ei ole>>, and the noun takes the partitive.", "language": "en", "pause_after_ms": 1000}, {"text": "Mul ei ole autot.", "language": "et", "pause_after_ms": 2400}, {"text": "I don't have a car. <<Mul ei ole auto>> is wrong. The correct form is <<mul ei ole autot>>.", "language": "en", "pause_after_ms": 900}, {"text": "Now you try. Say this in Estonian: We have a dog.", "language": "en", "pause_after_ms": 3800}, {"text": "Meil on koer.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. We used <<meil>> for we, and <<on>> for have.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up, the owner takes the ending <<l>>, followed by <<on>>. In the negative, use <<ei ole>> and the partitive.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson!", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Genitive Case (omastav)</b>

The genitive shows whose something is: "the dog's name", "the city's centre". It answers <i>kelle?</i> (whose?) and <i>mille?</i> (of what?). The owner always comes first, as in English "the dog's name" — never after, as in "the name of the dog".

📌 The singular genitive ends in a vowel, but the vowel varies, so learn it with each word:
<code>koer → koera</code>
<code>raamat → raamatu</code>
<code>linn → linna</code>
<code>maja → maja</code> (no change)
<code>mina → minu</code>, <code>sina → sinu</code>

💬 <i>See on koera nimi.</i> — This is the dog's name.
💬 <i>Raamatu hind on kõrge.</i> — The book's price is high.
💬 <i>Linna keskus on ilus.</i> — The city centre is beautiful.
💬 <i>Maja uks on punane.</i> — The door of the house is red.
💬 <i>Minu ema on arst.</i> — My mother is a doctor.

⚠️ Estonian has no word for "of" and no 's: the genitive ending does the job, and only the owner changes: <i>koera nimi</i> — <i>nimi</i> stays unchanged. Some words also change inside: <code>tuba → toa</code> (room).

💡 Many cases are built on the genitive: <code>raamatu → raamatus</code> (in the book), <code>linna → linnas</code> (in the city).$c$ WHERE id = 'a1-genitive-case';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-genitive-case', 'en', $s$[{"text": "Hello! Today we're learning the genitive case, called <<omastav>> in Estonian. You need it to say who or what something belongs to.", "language": "en", "pause_after_ms": 1000}, {"text": "The rule is simple. The owner comes first and takes the genitive ending. The thing that is owned stays unchanged.", "language": "en", "pause_after_ms": 1000}, {"text": "The singular genitive ends in a vowel, but the vowel changes from word to word. So learn each new word together with its genitive.", "language": "en", "pause_after_ms": 1000}, {"text": "See on koera nimi.", "language": "et", "pause_after_ms": 2400}, {"text": "This is the dog's name. <<Koer>> becomes <<koera>>, and <<nimi>> stays the same.", "language": "en", "pause_after_ms": 900}, {"text": "Raamatu hind on kõrge.", "language": "et", "pause_after_ms": 2400}, {"text": "The book's price is high. <<Raamat>> gets an extra vowel and becomes <<raamatu>>.", "language": "en", "pause_after_ms": 900}, {"text": "Linna keskus on ilus.", "language": "et", "pause_after_ms": 2400}, {"text": "The city centre is beautiful. <<Linn>> becomes <<linna>>.", "language": "en", "pause_after_ms": 900}, {"text": "Maja uks on punane.", "language": "et", "pause_after_ms": 2400}, {"text": "The door of the house is red. <<Maja>> doesn't change at all. Its genitive is also <<maja>>.", "language": "en", "pause_after_ms": 900}, {"text": "Minu ema on arst.", "language": "et", "pause_after_ms": 2400}, {"text": "My mother is a doctor. Pronouns have a genitive too. <<Mina>> becomes <<minu>>, which means my.", "language": "en", "pause_after_ms": 1000}, {"text": "Watch out. English can say the dog's name or the name of the dog. Estonian has only one pattern: the owner first, in the genitive, then the thing.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say this in Estonian: This is the map of the city.", "language": "en", "pause_after_ms": 3800}, {"text": "See on linna kaart.", "language": "et", "pause_after_ms": 2400}, {"text": "Well done. <<Linn>> becomes <<linna>> in the genitive, and <<kaart>> doesn't change.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: the owner comes first and takes the genitive. This case is also the base for many other cases.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson!", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Plural Formation Basics</b>

To talk about more than one thing (the subject or after <code>on</code>), Estonian uses the nominative plural. Rule: take the genitive singular and add <code>-d</code>.

📌 nominative → genitive → plural:
<code>raamat → raamatu → raamatud</code>
<code>laps → lapse → lapsed</code>
<code>linn → linna → linnad</code>
<code>tuba → toa → toad</code>
<code>see → need</code> (this → these, irregular)

💬 <i>Need on raamatud.</i> — These are the books.
💬 <i>Lapsed on koolis.</i> — The children are at school.
💬 <i>Linnad on suured.</i> — The cities are big.
💬 <i>Toad on puhtad.</i> — The rooms are clean.
💬 <i>Kus on minu võtmed?</i> — Where are my keys?

⚠️ Do not add <code>-d</code> to the dictionary form: <i>lapsd</i> is wrong, <i>lapsed</i> is right. And unlike English "two books", the noun after a number is not plural: <i>kaks raamatut</i>.

💡 Once you know a word's genitive, its plural costs just one letter: <code>võti → võtme → võtmed</code>.$c$ WHERE id = 'a1-plural-formation';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-plural-formation', 'en', $s$[{"text": "Hello! Today we're learning how to make Estonian nouns plural. You need this whenever you talk about more than one thing.", "language": "en", "pause_after_ms": 1000}, {"text": "Here's the rule. Take the singular genitive of the word and add the letter <<d>>. It does the job of the English plural s.", "language": "en", "pause_after_ms": 1000}, {"text": "For example, the genitive of <<raamat>> is <<raamatu>>. Add <<d>> and you get <<raamatud>>, books.", "language": "en", "pause_after_ms": 1000}, {"text": "Need on raamatud.", "language": "et", "pause_after_ms": 2400}, {"text": "These are the books. In the plural, <<see>>, meaning this, becomes <<need>>, meaning these.", "language": "en", "pause_after_ms": 900}, {"text": "Lapsed on koolis.", "language": "et", "pause_after_ms": 2400}, {"text": "The children are at school. The genitive of <<laps>> is <<lapse>>, so the plural is <<lapsed>>.", "language": "en", "pause_after_ms": 900}, {"text": "Linnad on suured.", "language": "et", "pause_after_ms": 2400}, {"text": "The cities are big. Both the noun and the adjective take the plural ending: <<linnad>> and <<suured>>.", "language": "en", "pause_after_ms": 900}, {"text": "Toad on puhtad.", "language": "et", "pause_after_ms": 2400}, {"text": "The rooms are clean. The genitive of <<tuba>> is <<toa>>, so the plural is <<toad>>.", "language": "en", "pause_after_ms": 900}, {"text": "Kus on minu võtmed?", "language": "et", "pause_after_ms": 2400}, {"text": "Where are my keys? The genitive of <<võti>> is <<võtme>>, and the plural is <<võtmed>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Watch out. Don't add <<d>> to the dictionary form. <<Lapsd>> is wrong. The right form is <<lapsed>>.", "language": "en", "pause_after_ms": 1000}, {"text": "One more thing. After numbers, Estonian doesn't use the plural. English says two books, but Estonian says <<kaks raamatut>>, with a singular noun.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. The genitive of <<maja>> is also <<maja>>. Say this in Estonian: The houses are big.", "language": "en", "pause_after_ms": 3800}, {"text": "Majad on suured.", "language": "et", "pause_after_ms": 2400}, {"text": "Well done. We added <<d>> to <<maja>> and got <<majad>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: for the plural, take the singular genitive and add <<d>>. And after numbers, no plural.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson!", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Partitive Case (osastav)</b>

The partitive is one of Estonian's most frequent cases. It answers <i>keda?</i> (whom?) and <i>mida?</i> (what?). At A1 use it in four situations: after numbers from two up, for unspecified amounts, in negative sentences and for ongoing actions or feelings.

📌 Endings: <code>-t</code>, <code>-d</code> or a vowel — learn it per word:
<code>raamat → raamatut</code>, <code>auto → autot</code>, <code>tee → teed</code>
<code>koer → koera</code>, <code>piim → piima</code>, <code>kohv → kohvi</code>

💬 <i>Ma joon kohvi.</i> — I drink coffee.
💬 <i>Mul on kaks koera.</i> — I have two dogs.
💬 <i>Mul ei ole autot.</i> — I don't have a car.
💬 <i>Ma loen raamatut.</i> — I am reading a book.
💬 <i>Ma armastan sind.</i> — I love you.

⚠️ English puts the noun after a number in the plural (two dogs). In Estonian <i>kaks koer</i> is wrong — say <i>kaks koera</i>, a singular partitive. Also, in a negative sentence the object (or the thing you don't have) goes into the partitive: <i>Mul ei ole autot</i>, not <i>auto</i>.

💡 Memory hook: numbers, amounts, "not", "in progress" → partitive.$c$ WHERE id = 'a1-partitive-case';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-partitive-case', 'en', $s$[{"text": "Hello! Today we're learning one of the most common Estonian cases, the partitive, called <<osastav>>.", "language": "en", "pause_after_ms": 1000}, {"text": "We use it in four situations: after numbers from two up, for unspecified amounts, in negative sentences, and for ongoing actions.", "language": "en", "pause_after_ms": 1000}, {"text": "Often you add <<t>> to the genitive, so <<raamatu>> becomes <<raamatut>>. Sometimes the two cases look the same: <<piim>> gives <<piima>> in both.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma joon kohvi.", "language": "et", "pause_after_ms": 2400}, {"text": "I drink coffee. The amount isn't specified, so <<kohv>> becomes <<kohvi>>.", "language": "en", "pause_after_ms": 900}, {"text": "Mul on kaks koera.", "language": "et", "pause_after_ms": 2400}, {"text": "I have two dogs. After numbers from two up, the noun is in the singular partitive: <<koera>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Mul ei ole autot.", "language": "et", "pause_after_ms": 2400}, {"text": "I don't have a car. In a negative sentence, the thing you don't have goes into the partitive: <<auto>> becomes <<autot>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma loen raamatut.", "language": "et", "pause_after_ms": 2400}, {"text": "I am reading a book. The action is still going on, so the object is <<raamatut>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma armastan sind.", "language": "et", "pause_after_ms": 2400}, {"text": "I love you. The object of loving is always in this case: <<sina>> becomes <<sind>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Watch out. English says two dogs, with a plural noun. In Estonian <<kaks koer>> is wrong. The correct form is <<kaks koera>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say this in Estonian: I don't drink milk.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma ei joo piima.", "language": "et", "pause_after_ms": 2400}, {"text": "Well done. In a negative sentence, <<piim>> becomes <<piima>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: use the partitive after numbers, for unspecified amounts, for the object of a negative sentence, and for ongoing actions.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson!", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Adjective Agreement with Nouns</b>

In Estonian an adjective takes the same case and number as its noun. Whatever ending the noun gets, the adjective gets too.

📌 <code>suur maja</code> — a big house
<code>suure maja</code> — of a big house (genitive)
<code>suurt maja</code> — partitive
<code>suures majas</code> — in a big house
<code>suured majad</code> — big houses
<code>Maja on suur. → Majad on suured.</code>

💬 <i>Mul on suur maja.</i> — I have a big house.
💬 <i>Need on suured majad.</i> — These are big houses.
💬 <i>Ma elan suures majas.</i> — I live in a big house.
💬 <i>Ma ei näe punast autot.</i> — I don't see the red car.
💬 <i>Ta tuli väikese lapsega.</i> — She came with a small child.

⚠️ English adjectives never change (a big house, in big houses). In Estonian <i>suur majas</i> is wrong — say <i>suures majas</i>. Exception: with <code>-ga</code> (with), and later also <code>-ni</code>, <code>-na</code>, <code>-ta</code>, only the noun takes the ending and the adjective stays in the genitive: <i>väikese lapsega</i>.

💡 Adjective and noun travel together as a pair.$c$ WHERE id = 'a1-adjective-agreement';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-adjective-agreement', 'en', $s$[{"text": "Hello! Today we're learning how adjectives agree with nouns. This works very differently from English.", "language": "en", "pause_after_ms": 1000}, {"text": "In English an adjective never changes: a big house, in a big house. In Estonian the adjective takes the same case and number as its noun.", "language": "en", "pause_after_ms": 1000}, {"text": "Mul on suur maja.", "language": "et", "pause_after_ms": 2400}, {"text": "I have a big house. <<Suur>> and <<maja>> are both in the basic form.", "language": "en", "pause_after_ms": 900}, {"text": "Need on suured majad.", "language": "et", "pause_after_ms": 2400}, {"text": "These are big houses. In the plural the adjective also gets <<d>>: <<suured majad>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma elan suures majas.", "language": "et", "pause_after_ms": 2400}, {"text": "I live in a big house. When the noun takes the ending <<s>>, so does the adjective: <<suures majas>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ei näe punast autot.", "language": "et", "pause_after_ms": 2400}, {"text": "I don't see the red car. In a negative sentence both words are in the partitive: <<punast autot>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Toad on väikesed.", "language": "et", "pause_after_ms": 2400}, {"text": "The rooms are small. An adjective after the verb also agrees in number. With a plural subject we say <<väikesed>>.", "language": "en", "pause_after_ms": 900}, {"text": "There's one important exception. With the ending <<ga>>, and a few endings you'll meet later, only the noun takes the ending. The adjective stays in the genitive.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta tuli väikese lapsega.", "language": "et", "pause_after_ms": 2400}, {"text": "She came with a small child. We say <<väikese lapsega>>, not <<väikesega lapsega>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say this in Estonian: I live in a beautiful city.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma elan ilusas linnas.", "language": "et", "pause_after_ms": 2400}, {"text": "Well done. Like <<linnas>>, the adjective <<ilus>> takes the ending <<s>> and becomes <<ilusas>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: the adjective follows the noun's case and number. With a few endings, like <<ga>>, it stays in the genitive.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson!", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Telling Time (Mis kell on?)</b>
To ask the time, say <i>Mis kell on?</i> Full hours are easy; half and quarter hours always count toward the NEXT hour.

<code>kell on kolm</code> — 3:00
<code>pool</code> (half): <code>pool neli</code> — 3:30
<code>veerand</code> (quarter): <code>veerand neli</code> — 3:15
<code>kolmveerand</code> (three quarters): <code>kolmveerand neli</code> — 3:45
at a specific time: <code>kell kaheksa</code> — at eight

💬 <i>Mis kell on?</i> — What time is it?
💬 <i>Kell on pool seitse.</i> — It's half past six.
💬 <i>Kell on veerand kaks.</i> — It's quarter past one.
💬 <i>Kell on kolmveerand kaks.</i> — It's quarter to two.
💬 <i>Ma tulen kell kaheksa.</i> — I'll come at eight.

⚠️ English says "half past six", counting from the hour that has passed, but <i>pool seitse</i> means "half of seven" = 6:30. <i>Pool kuus</i> is 5:30, an hour earlier. If you know the casual British "half seven" (7:30), don't copy it: that is <i>pool kaheksa</i>.
💡 Picture the next hour filling up: at 6:30 the seventh hour is half full, so <i>pool seitse</i>.$c$ WHERE id = 'a1-telling-time';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-telling-time', 'en', $s$[{"text": "Hello. Today we're learning to ask and tell the time in Estonian. You'll need it every day, for meetings, buses and classes.", "language": "en", "pause_after_ms": 1000}, {"text": "Mis kell on?", "language": "et", "pause_after_ms": 2400}, {"text": "What time is it? This is how you ask for the time.", "language": "en", "pause_after_ms": 900}, {"text": "For full hours, say <<kell on>> and then the number.", "language": "en", "pause_after_ms": 900}, {"text": "Kell on üks.", "language": "et", "pause_after_ms": 2400}, {"text": "It's one o'clock. Full hours are just as easy as in English.", "language": "en", "pause_after_ms": 900}, {"text": "But for halves and quarters, Estonian always counts toward the next hour.", "language": "en", "pause_after_ms": 1000}, {"text": "Kell on pool seitse.", "language": "et", "pause_after_ms": 2400}, {"text": "It's half past six. <<Pool>> means half. Word for word, it's half of seven.", "language": "en", "pause_after_ms": 900}, {"text": "Kell on veerand kaks.", "language": "et", "pause_after_ms": 2400}, {"text": "It's quarter past one. <<Veerand>> means a quarter: the first quarter of the second hour.", "language": "en", "pause_after_ms": 900}, {"text": "Kell on kolmveerand kaks.", "language": "et", "pause_after_ms": 2400}, {"text": "It's quarter to two. <<Kolmveerand>> means three quarters.", "language": "en", "pause_after_ms": 900}, {"text": "Ma tulen kell kaheksa.", "language": "et", "pause_after_ms": 2400}, {"text": "I'll come at eight. To say at a certain time, just use <<kell>> and the number. No ending is needed.", "language": "en", "pause_after_ms": 1000}, {"text": "The most common mistake is thinking half past six and saying <<pool kuus>>. But that actually means half past five.", "language": "en", "pause_after_ms": 1100}, {"text": "Now you try. How do you say half past four in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Kell on pool viis.", "language": "et", "pause_after_ms": 2400}, {"text": "Well done. At half past four, the fifth hour is half gone, so we say <<pool viis>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: for full hours, <<kell on>> and the number. For halves and quarters, name the next hour.", "language": "en", "pause_after_ms": 1000}, {"text": "Every time you check the clock today, try saying the time in Estonian. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Basic Adverbs of Time and Place</b>
These words say when and where something happens. No case endings are added. If one comes first, the verb usually comes next: <i>Täna on…</i>

⏰ Time: <code>täna</code> today · <code>homme</code> tomorrow · <code>eile</code> yesterday · <code>nüüd</code> now · <code>praegu</code> right now
📍 Place (where?): <code>siin</code> here · <code>seal</code> there · <code>kodus</code> at home · <code>väljas</code> outside
➡️ Direction (where to?): <code>siia</code> (to) here · <code>sinna</code> (to) there · <code>koju</code> home

💬 <i>Täna on esmaspäev.</i> — Today is Monday.
💬 <i>Eile sadas vihma.</i> — It rained yesterday.
💬 <i>Homme läheme poodi.</i> — Tomorrow we're going to the shop.
💬 <i>Ma olen praegu kodus.</i> — I'm at home right now.
💬 <i>Lapsed mängivad väljas.</i> — The children are playing outside.

⚠️ English uses "here" for both "I am here" and "Come here", but Estonian has separate words for location and direction: <i>Ma olen siin</i> but <i>Tule siia!</i>, not <i>Tule siin</i>.
💡 Learn them in pairs: <i>siin – siia</i>, <i>seal – sinna</i>, <i>kodus – koju</i>.$c$ WHERE id = 'a1-adverbs-time-place';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-adverbs-time-place', 'en', $s$[{"text": "Hello. Today we're learning short words that answer when and where. With them you can build simple sentences right away.", "language": "en", "pause_after_ms": 1000}, {"text": "For time: <<täna>> means today, <<homme>> tomorrow, <<eile>> yesterday, and <<nüüd>> now.", "language": "en", "pause_after_ms": 1000}, {"text": "Täna on esmaspäev.", "language": "et", "pause_after_ms": 2400}, {"text": "Today is Monday. When <<täna>> comes first, the verb usually comes right after it: <<täna on>>.", "language": "en", "pause_after_ms": 900}, {"text": "Eile sadas vihma.", "language": "et", "pause_after_ms": 2400}, {"text": "It rained yesterday. With <<eile>>, the verb is in the past tense: <<sadas>>.", "language": "en", "pause_after_ms": 900}, {"text": "Homme läheme poodi.", "language": "et", "pause_after_ms": 2400}, {"text": "Tomorrow we're going to the shop. Estonian has no separate future tense. The present tense plus <<homme>> talks about the future.", "language": "en", "pause_after_ms": 1000}, {"text": "For place: <<siin>> means here, <<seal>> there, <<kodus>> at home, and <<väljas>> outside.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma olen praegu kodus.", "language": "et", "pause_after_ms": 2400}, {"text": "I'm at home right now. <<Praegu>> means right now.", "language": "en", "pause_after_ms": 900}, {"text": "Lapsed mängivad väljas.", "language": "et", "pause_after_ms": 2400}, {"text": "The children are playing outside. <<Väljas>> answers the question where.", "language": "en", "pause_after_ms": 900}, {"text": "Watch out. English uses here for both being and moving. Estonian doesn't: <<siin>> is here, but <<siia>> is to here. <<Seal>> is there, <<sinna>> is to there.", "language": "en", "pause_after_ms": 1000}, {"text": "Tule siia!", "language": "et", "pause_after_ms": 2400}, {"text": "Come here! There's movement, so we use <<siia>>, not <<siin>>.", "language": "en", "pause_after_ms": 900}, {"text": "Now you try. Say this in Estonian: I'm at home tomorrow.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma olen homme kodus.", "language": "et", "pause_after_ms": 2400}, {"text": "Well done. <<Homme>> means tomorrow, and <<kodus>> means at home.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: time words answer when, place words answer where. For direction there are separate words, like <<siia>> and <<sinna>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Today, try describing your day with these words. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>With (-ga) and Without (-ta)</b>
Use <code>-ga</code> for "with" (people, things, transport) and <code>-ta</code> for "without". Both are added to the genitive form of the word.

<code>piim → piima → piimaga</code> with milk
<code>buss → bussi → bussiga</code> by bus
<code>suhkur → suhkru → suhkruta</code> without sugar
<code>sina → sinu → sinuga</code> with you

💬 <i>Ma joon kohvi piimaga.</i> — I drink coffee with milk.
💬 <i>Ma sõidan tööle bussiga.</i> — I go to work by bus.
💬 <i>Ma räägin emaga.</i> — I'm talking with my mother.
💬 <i>Ma joon teed suhkruta.</i> — I drink tea without sugar.
💬 <i>Ta tuli ilma jopeta.</i> — He came without a jacket.

⚠️ Don't attach the ending to the dictionary form: <i>suhkruta</i>, not <i>suhkurta</i>. English puts a separate word before the noun; Estonian puts an ending after the genitive. The word <i>ilma</i> before <i>-ta</i> is optional emphasis.
💡 Note that "by bus" is also <i>-ga</i>: any tool or vehicle you use takes it. Learn each noun with its genitive.$c$ WHERE id = 'a1-comitative-abessive';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-comitative-abessive', 'en', $s$[{"text": "Hello. Today we're learning two very useful endings: <<ga>>, meaning with, and <<ta>>, meaning without. You'll use them in cafes and on the road.", "language": "en", "pause_after_ms": 1000}, {"text": "Here's the rule. Both endings go on the genitive form of the word. <<Piim>> means milk, its genitive is <<piima>>, so with milk is <<piimaga>>.", "language": "en", "pause_after_ms": 1100}, {"text": "Ma joon kohvi piimaga.", "language": "et", "pause_after_ms": 2400}, {"text": "I drink coffee with milk. The ending <<ga>> does the job of the English word with: <<piimaga>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma sõidan tööle bussiga.", "language": "et", "pause_after_ms": 2400}, {"text": "I go to work by bus. For vehicles we also use <<ga>>, where English says by.", "language": "en", "pause_after_ms": 900}, {"text": "Ma räägin emaga.", "language": "et", "pause_after_ms": 2400}, {"text": "I'm talking with my mother. The same ending works for people: <<emaga>>.", "language": "en", "pause_after_ms": 900}, {"text": "Now for without. The same genitive form takes the ending <<ta>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma joon teed suhkruta.", "language": "et", "pause_after_ms": 2400}, {"text": "I drink tea without sugar. The genitive of <<suhkur>> is <<suhkru>>, so we say <<suhkruta>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta tuli ilma jopeta.", "language": "et", "pause_after_ms": 2400}, {"text": "He came without a jacket. The word <<ilma>> makes without stronger, but you can leave it out.", "language": "en", "pause_after_ms": 900}, {"text": "A common mistake is adding the ending to the dictionary form. <<Suhkurta>> is wrong. The right form is <<suhkruta>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say this in Estonian: I'm coming with you. You is <<sina>>, and its genitive is <<sinu>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma tulen sinuga.", "language": "et", "pause_after_ms": 2400}, {"text": "Well done. We added <<ga>> to <<sinu>>: <<sinuga>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: on the genitive, the ending <<ga>> means with, and the ending <<ta>> means without.", "language": "en", "pause_after_ms": 1000}, {"text": "Next time, try ordering your coffee in Estonian. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>MA vs DA Infinitive</b>
Estonian has two "to do" forms. Dictionaries list verbs in the <code>-ma</code> form; the verb before it decides which one you need.

<code>-ma</code> after going, coming and <code>hakkama</code> (to start):
<code>Ma lähen / tulen / hakkan + õppima</code>
<code>-da</code> after wanting, liking and knowing how:
<code>Ma tahan / oskan, mulle meeldib + õppida</code>
Common pairs: <code>õppima → õppida</code>, <code>ujuma → ujuda</code>, <code>sööma → süüa</code>

💬 <i>Ma lähen sööma.</i> — I'm going to eat.
💬 <i>Ma hakkan homme töötama.</i> — I start working tomorrow.
💬 <i>Ma tahan eesti keelt õppida.</i> — I want to learn Estonian.
💬 <i>Mulle meeldib tantsida.</i> — I like dancing.
💬 <i>Ma oskan ujuda.</i> — I can swim.

⚠️ <i>Ma tahan õppima</i> is wrong: after <i>tahtma</i> always use <i>-da</i>, so <i>Ma tahan õppida</i>.
💡 English "to" covers both forms, so learn the groups: going, coming, starting → <i>-ma</i>; wanting, liking, knowing how → <i>-da</i>. And <i>Ma lähen sööma</i> means you are really off to eat, not the English "going to" future.$c$ WHERE id = 'a1-ma-da-infinitive';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-ma-da-infinitive', 'en', $s$[{"text": "Hello. Today we're learning the two Estonian infinitive forms: the <<ma>> form and the <<da>> form. You'll need both every day to join two verbs.", "language": "en", "pause_after_ms": 1000}, {"text": "Dictionaries list verbs in the <<ma>> form, for example <<õppima>>, to learn. The other form is <<õppida>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Here's the rule. After going, coming and starting, use <<ma>>. After wanting, liking and knowing how, use <<da>>.", "language": "en", "pause_after_ms": 1100}, {"text": "Ma lähen sööma.", "language": "et", "pause_after_ms": 2400}, {"text": "I'm going to eat. After the verb for going comes <<sööma>>, the <<ma>> form.", "language": "en", "pause_after_ms": 900}, {"text": "Ma hakkan homme töötama.", "language": "et", "pause_after_ms": 2400}, {"text": "I start working tomorrow. <<Hakkama>> means to start, and it always takes the <<ma>> form.", "language": "en", "pause_after_ms": 900}, {"text": "Ma tahan eesti keelt õppida.", "language": "et", "pause_after_ms": 2400}, {"text": "I want to learn Estonian. After wanting comes <<õppida>>.", "language": "en", "pause_after_ms": 900}, {"text": "Mulle meeldib tantsida.", "language": "et", "pause_after_ms": 2400}, {"text": "I like dancing. <<Meeldib>> means something is pleasing to you, and the <<da>> form follows it.", "language": "en", "pause_after_ms": 900}, {"text": "Ma oskan ujuda.", "language": "et", "pause_after_ms": 2400}, {"text": "I can swim. <<Oskama>> means to know how to do something, and <<ujuda>> follows it.", "language": "en", "pause_after_ms": 900}, {"text": "English won't help you choose, because both forms are just to plus a verb. So think about the meaning: going and starting take <<ma>>, wanting and knowing how take <<da>>.", "language": "en", "pause_after_ms": 1100}, {"text": "A common mistake is saying <<ma tahan õppima>>. After wanting, always use the <<da>> form.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say this in Estonian: I'm going swimming. To swim is <<ujuma>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma lähen ujuma.", "language": "et", "pause_after_ms": 2400}, {"text": "Well done. After going, the <<ma>> form: <<ujuma>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: after going, coming and starting, use <<ma>>. After wanting, liking and knowing how, use <<da>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Learn every new verb in both forms. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Clothing: Where Is It Worn?</b>
To say someone is wearing something, Estonian says they "have it on" a body part: <code>Mul on</code> + clothing + body part with <code>-s</code> (in/on).

<code>pea → peas</code> on the head: müts
<code>kael → kaelas</code> around the neck: sall, lips
<code>selg → seljas</code> on the body (lit. on the back): särk, kampsun, jope
<code>jalg → jalas</code> on the legs or feet: püksid, saapad
<code>käsi → käes</code> on the hands: kindad
<code>ees</code> in front, on the face: prillid

💬 <i>Tal on müts peas.</i> — He has a hat on.
💬 <i>Mul on jope seljas.</i> — I'm wearing a jacket.
💬 <i>Tal on saapad jalas.</i> — She's wearing boots.
💬 <i>Mul on kindad käes.</i> — I have gloves on.
💬 <i>Tal on prillid ees.</i> — He's wearing glasses.

⚠️ The body part stays singular, even for pairs: <i>kindad käes</i>, <i>saapad jalas</i>, not <i>kätes</i> or <i>jalgades</i>. Trousers go <i>jalas</i>, not <i>seljas</i>.
💡 English says "I'm wearing"; Estonian asks where the item sits: <i>peas, kaelas, seljas, jalas, käes</i>.$c$ WHERE id = 'a1-clothing-locations';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a1-clothing-locations', 'en', $s$[{"text": "Hello. Today we're learning how to say what someone is wearing in Estonian. In the cold Estonian winter you'll hear these sentences a lot.", "language": "en", "pause_after_ms": 1000}, {"text": "Instead of a verb like wear, Estonian usually says something like: he has a hat on his head. The body part takes the ending <<s>>, meaning in or on.", "language": "en", "pause_after_ms": 1000}, {"text": "<<Pea>> is head, <<peas>> on the head. <<Selg>> is back, <<seljas>> on the back. <<Jalg>> is leg or foot, <<jalas>> on the legs.", "language": "en", "pause_after_ms": 1000}, {"text": "Tal on müts peas.", "language": "et", "pause_after_ms": 2400}, {"text": "He has a hat on. <<Tal on>> means he has, or she has.", "language": "en", "pause_after_ms": 900}, {"text": "Mul on jope seljas.", "language": "et", "pause_after_ms": 2400}, {"text": "I'm wearing a jacket. <<Seljas>> means on the back, but it's used for most clothes on your body.", "language": "en", "pause_after_ms": 900}, {"text": "Tal on saapad jalas.", "language": "et", "pause_after_ms": 2400}, {"text": "She's wearing boots. Trousers are <<jalas>> too.", "language": "en", "pause_after_ms": 900}, {"text": "Mul on kindad käes.", "language": "et", "pause_after_ms": 2400}, {"text": "I have gloves on. <<Käsi>> is hand, <<käes>> on the hand.", "language": "en", "pause_after_ms": 900}, {"text": "Tal on prillid ees.", "language": "et", "pause_after_ms": 2400}, {"text": "He's wearing glasses. For glasses we say <<ees>>, meaning in front.", "language": "en", "pause_after_ms": 900}, {"text": "A common mistake is using the plural. You have two hands, but Estonian says singular <<käes>>, not <<kätes>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say: She has a scarf on. Scarf is <<sall>>, and neck is <<kael>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Tal on sall kaelas.", "language": "et", "pause_after_ms": 2400}, {"text": "Well done. <<Kael>> became <<kaelas>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: <<mul on>>, then the clothing, then the body part with the ending <<s>>. First think about where the item sits.", "language": "en", "pause_after_ms": 1000}, {"text": "Today, try naming what you're wearing in Estonian. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();

--changeset english-grammar-content:a2 splitStatements:false
UPDATE grammar_lessons SET content = $c$<b>Numbers 11–100 and Ordinals</b>

Building on 1–10, two patterns give you every number up to 100.

📌 11–19: number + <code>-teist</code>
<code>üksteist</code> 11, <code>kaksteist</code> 12, <code>viisteist</code> 15
📌 Tens: number + <code>-kümmend</code>
<code>kakskümmend</code> 20, <code>kolmkümmend</code> 30, <code>üheksakümmend</code> 90
📌 Tens + units: <code>kakskümmend viis</code> 25; 100 is <code>sada</code>
📌 Ordinals: <code>esimene, teine, kolmas, neljas, viies, kümnes</code>

💬 <i>Klassis on kakskümmend õpilast.</i> — There are twenty students in the class.
💬 <i>See maksab viisteist eurot.</i> — This costs fifteen euros.
💬 <i>Ta on nelikümmend kaks aastat vana.</i> — He is forty-two years old.
💬 <i>Ma elan kolmandal korrusel.</i> — I live on the third floor.

⚠️ After a number the noun is partitive SINGULAR: <i>kakskümmend õpilast</i>, not <i>õpilasi</i>. English says "twenty students" with a plural, so resist the urge to make the noun plural.

💡 Ordinals take the same case ending as their noun: <i>kolmandal korrusel</i>. English "third" never changes, so this agreement is easy to forget.$c$ WHERE id = 'a2-numbers-11-100';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-numbers-11-100', 'en', $s$[{"text": "Hello. You already know the numbers from one to ten. Today we learn eleven to one hundred, and ordinal numbers too. You need them for prices, ages and addresses.", "language": "en", "pause_after_ms": 900}, {"text": "Eleven to nineteen are easy. You add <<teist>> to the number. <<üks>> means one, and <<üksteist>> means eleven.", "language": "en", "pause_after_ms": 1000}, {"text": "Üksteist, kaksteist, kolmteist.", "language": "et", "pause_after_ms": 2400}, {"text": "Eleven, twelve, thirteen. All of these follow the same pattern.", "language": "en", "pause_after_ms": 900}, {"text": "For the tens, you add <<kümmend>>. <<kaks>> means two, and <<kakskümmend>> means twenty. Then the units follow.", "language": "en", "pause_after_ms": 1000}, {"text": "Kakskümmend, kolmkümmend, nelikümmend.", "language": "et", "pause_after_ms": 2400}, {"text": "Twenty, thirty, forty. One hundred is a single word, <<sada>>.", "language": "en", "pause_after_ms": 900}, {"text": "Klassis on kakskümmend õpilast.", "language": "et", "pause_after_ms": 2400}, {"text": "There are twenty students in the class. After a number, the noun is in the partitive singular, <<õpilast>>.", "language": "en", "pause_after_ms": 900}, {"text": "See maksab viisteist eurot.", "language": "et", "pause_after_ms": 2400}, {"text": "This costs fifteen euros. The word <<euro>> takes the partitive here and becomes <<eurot>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ta on nelikümmend kaks aastat vana.", "language": "et", "pause_after_ms": 2400}, {"text": "He is forty-two years old. Just like in English, the tens come first and then the units.", "language": "en", "pause_after_ms": 900}, {"text": "Now the ordinals. <<esimene>> means first, <<teine>> second, <<kolmas>> third, and <<neljas>> fourth.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma elan kolmandal korrusel.", "language": "et", "pause_after_ms": 2400}, {"text": "I live on the third floor. <<kolmas>> becomes <<kolmandal>> here, because the ordinal takes the same ending <<l>> as its noun.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake for English speakers is a plural after the number. We say <<õpilast>>, not <<õpilasi>>, even though English says twenty students.", "language": "en", "pause_after_ms": 1000}, {"text": "Now it's your turn. Say thirty-five euros in Estonian.", "language": "en", "pause_after_ms": 3800}, {"text": "Kolmkümmend viis eurot.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. First <<kolmkümmend>>, then <<viis>>, and finally <<eurot>> in the partitive.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up, we use <<teist>> for eleven to nineteen, and <<kümmend>> for the tens. After a number, the noun is partitive singular.", "language": "en", "pause_after_ms": 900}, {"text": "That's all for today. See you in the next lesson, <<head aega>>.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Basic conjunctions: ja, aga, või, sest, et, kui</b>
Conjunctions join words and clauses. These six cover most everyday needs.

🔹 <code>ja</code> and · <code>aga</code> but · <code>või</code> or
🔹 <code>sest</code> because · <code>et</code> that · <code>kui</code> if, when
🔹 After <code>et</code>, <code>sest</code> and <code>kui</code> comes a full clause with its own subject and conjugated verb, just as after English "that", "because" and "if"

💬 <i>Ma joon kohvi ja loen ajalehte.</i> — I drink coffee and read the newspaper.
💬 <i>Ma tahan tulla, aga mul ei ole aega.</i> — I want to come, but I don't have time.
💬 <i>Ma jään koju, sest sajab vihma.</i> — I'm staying at home because it's raining.
💬 <i>Ma tean, et ta on kodus.</i> — I know that he is at home.
💬 <i>Kui sa tuled, helista mulle.</i> — If you come, call me.

⚠️ Put a comma before <code>aga</code>, <code>sest</code> and <code>et</code>, and after a clause starting with <code>kui</code>. No comma before a simple <code>ja</code>.
💡 English often drops "that" (<i>I know he's at home</i>), but Estonian keeps <code>et</code> and always puts a comma before it: <i>Ma tean, et ta on kodus</i>.$c$ WHERE id = 'a2-conjunctions';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-conjunctions', 'en', $s$[{"text": "Hello. Today we learn six basic conjunctions. With them you can join short sentences and sound much more natural.", "language": "en", "pause_after_ms": 1000}, {"text": "<<ja>> means and, <<aga>> means but, and <<või>> means or. <<sest>> means because, <<et>> means that, and <<kui>> means if or when.", "language": "en", "pause_after_ms": 1000}, {"text": "Good news for English speakers. After <<et>>, <<sest>> and <<kui>> comes a full clause with its own subject and verb, just like after that, because and if in English.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma joon kohvi ja loen ajalehte.", "language": "et", "pause_after_ms": 2400}, {"text": "I drink coffee and read the newspaper. <<ja>> joins two actions, and there is no comma before it.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma tahan tulla, aga mul ei ole aega.", "language": "et", "pause_after_ms": 2400}, {"text": "I want to come, but I don't have time. <<aga>> shows a contrast, and it always has a comma before it.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma jään koju, sest sajab vihma.", "language": "et", "pause_after_ms": 2400}, {"text": "I'm staying at home because it's raining. <<sest>> gives the reason, and the reason comes after it.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma tean, et ta on kodus.", "language": "et", "pause_after_ms": 2400}, {"text": "I know that he is at home. In English you can drop that, but in Estonian you keep <<et>>, with a comma before it.", "language": "en", "pause_after_ms": 1000}, {"text": "Kui sa tuled, helista mulle.", "language": "et", "pause_after_ms": 2400}, {"text": "If you come, call me. <<kui>> can start the sentence, and then we put a comma at the end of that clause.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is forgetting the comma before <<aga>>, <<sest>> and <<et>>. English often leaves it out, but Estonian always uses it.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Ask a friend whether they want tea or coffee.", "language": "en", "pause_after_ms": 3800}, {"text": "Kas sa tahad teed või kohvi?", "language": "et", "pause_after_ms": 2400}, {"text": "Do you want tea or coffee? <<või>> joins the two choices, and <<kas>> at the start marks the question.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, <<ja>>, <<aga>> and <<või>> join equal parts. <<sest>>, <<et>> and <<kui>> start a clause and are separated by a comma.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Inessive -s (IN) and Elative -st (OUT OF)</b>

These cases complete the illative: <i>kuhu?</i> → <i>kus?</i> → <i>kust?</i> The inessive says where something is inside; the elative says what it comes out of.

📌 Both endings go on the genitive stem:
<code>kool → koolis → koolist</code>
<code>kott → kotis → kotist</code>
<code>pood → poes → poest</code>

💬 <i>Ma elan Tallinnas.</i> — I live in Tallinn.
💬 <i>Raamat on kotis.</i> — The book is in the bag.
💬 <i>Ta tuleb koolist.</i> — He is coming from school.
💬 <i>Võta piim külmkapist.</i> — Take the milk out of the fridge.
💬 <i>Me räägime filmist.</i> — We are talking about the film.

⚠️ Use the genitive stem, not the base form: <i>kotis</i>, not <i>kottis</i>; <i>poes</i>, not <i>poodis</i>. And <code>-s</code> is only for INSIDE, like English "in": on the table is <i>laual</i>, not <i>lauas</i>.

💡 <code>-st</code> covers English "out of" and "from (inside)": <i>koolist</i> = from school. <i>Rääkima</i> (to talk) also takes the elative where English uses "about".$c$ WHERE id = 'a2-inessive-elative';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-inessive-elative', 'en', $s$[{"text": "Hello. Today we learn two related cases, <<seesütlev>> and <<seestütlev>>. They tell us that something is inside a place, or that it comes out of a place.", "language": "en", "pause_after_ms": 900}, {"text": "The inessive answers <<kus>>, where, and takes the ending <<s>>. The elative answers <<kust>>, where from, and takes the ending <<st>>.", "language": "en", "pause_after_ms": 1000}, {"text": "These endings go on the genitive stem. For example, the genitive of <<kott>> is <<koti>>, so we say <<kotis>> and <<kotist>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma elan Tallinnas.", "language": "et", "pause_after_ms": 2400}, {"text": "I live in <<Tallinn>>. To say you are inside a city, you use the ending <<s>>.", "language": "en", "pause_after_ms": 900}, {"text": "Raamat on kotis.", "language": "et", "pause_after_ms": 2400}, {"text": "The book is in the bag. Notice that <<kotis>> has only one <<t>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ta tuleb koolist.", "language": "et", "pause_after_ms": 2400}, {"text": "He is coming from school. The ending <<st>> works like English from, or out of.", "language": "en", "pause_after_ms": 900}, {"text": "Ma ostan poest leiba.", "language": "et", "pause_after_ms": 2400}, {"text": "I buy bread from the shop. The genitive of <<pood>> is <<poe>>, so we say <<poest>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Võta piim külmkapist.", "language": "et", "pause_after_ms": 2400}, {"text": "Take the milk out of the fridge. When you take something out from inside, you use the elative too.", "language": "en", "pause_after_ms": 900}, {"text": "Me räägime filmist.", "language": "et", "pause_after_ms": 2400}, {"text": "We are talking about the film. The verb <<rääkima>> puts the topic in the elative, where English says about.", "language": "en", "pause_after_ms": 900}, {"text": "Here is a common mistake. The ending <<s>> means inside, like English in. Don't use it for on.", "language": "en", "pause_after_ms": 1000}, {"text": "For a book on the table, we say <<laual>>, not <<lauas>>. We will look at this closely in the lesson on surface cases.", "language": "en", "pause_after_ms": 1000}, {"text": "Now it's your turn. Say I am at school in Estonian. School is <<kool>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma olen koolis.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. <<koolis>> means at school. For from school, we say <<koolist>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up, we say <<kooli>> for where to, <<koolis>> for where, and <<koolist>> for where from.", "language": "en", "pause_after_ms": 900}, {"text": "That's all for today. See you in the next lesson, <<head aega>>.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Illative Case (sisseütlev) — movement INTO</b>

The illative answers <i>kuhu?</i> (where to?) and shows movement into a place: a building, a room, a city or a country.

📌 Long form: genitive + <code>-sse</code>, works for almost every noun:
<code>maja → majasse</code>, <code>Tartu → Tartusse</code>
📌 Short form: many everyday words also have a short illative:
<code>linn → linna</code>, <code>kool → kooli</code>, <code>tuba → tuppa</code>, <code>pood → poodi</code>

💬 <i>Ma lähen linna.</i> — I am going to town.
💬 <i>Lapsed lähevad kooli.</i> — The children go to school.
💬 <i>Ta tuleb tuppa.</i> — She comes into the room.
💬 <i>Me sõidame Tartusse.</i> — We are going to Tartu (by bus, train or car).
💬 <i>Pane piim külmkappi.</i> — Put the milk in the fridge.

⚠️ English "to" covers every kind of direction. Estonian uses the illative only for going INSIDE; for people and surfaces it uses <code>-le</code>: <i>Ma annan raamatu sõbrale.</i> (not <i>sõbrasse</i>).

💡 Not sure about the short form? Add <code>-sse</code> to the genitive: <code>kool → koolisse</code> is also correct.$c$ WHERE id = 'a2-illative-case';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-illative-case', 'en', $s$[{"text": "Hello. Today we learn the illative case, <<sisseütlev>>. You need it every day to say that you are going into a place.", "language": "en", "pause_after_ms": 900}, {"text": "The illative answers <<kuhu>>, where to. It shows movement into a place, such as a school, a city or a room.", "language": "en", "pause_after_ms": 900}, {"text": "The long form is easy. You add <<sse>> to the genitive form of the word. For example, <<maja>> becomes <<majasse>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Some common words also have a short form. <<linn>> becomes <<linna>>, and <<kool>> becomes <<kooli>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma lähen linna.", "language": "et", "pause_after_ms": 2400}, {"text": "I am going to town. Here <<linna>> is the short illative form.", "language": "en", "pause_after_ms": 900}, {"text": "Lapsed lähevad kooli.", "language": "et", "pause_after_ms": 2400}, {"text": "The children go to school. Only the sound <<i>> was added to <<kool>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ta tuleb tuppa.", "language": "et", "pause_after_ms": 2400}, {"text": "She comes into the room. The short form of <<tuba>> is <<tuppa>>, and the consonant changes too.", "language": "en", "pause_after_ms": 900}, {"text": "Me sõidame Tartusse.", "language": "et", "pause_after_ms": 2400}, {"text": "We are going to <<Tartu>> by car, bus or train. Here we see the long form, <<Tartu>> becomes <<Tartusse>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Pane piim külmkappi.", "language": "et", "pause_after_ms": 2400}, {"text": "Put the milk in the fridge. <<külmkapp>> became <<külmkappi>>, because the milk goes inside the fridge.", "language": "en", "pause_after_ms": 900}, {"text": "Now pay attention. In English, you go to school and you give something to a friend, with the same word. In Estonian, for people you use the ending <<le>>, not the illative.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma annan raamatu sõbrale.", "language": "et", "pause_after_ms": 2400}, {"text": "I am giving the book to my friend. Saying <<sõbrasse>> would be wrong, because you are not going inside your friend.", "language": "en", "pause_after_ms": 1000}, {"text": "Now it's your turn. Say I am going to the shop in Estonian. Shop is <<pood>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma lähen poodi.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The short illative of <<pood>> is <<poodi>>. The long form <<poesse>> is also correct.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up, the illative answers <<kuhu>>. If you are not sure about the short form, add <<sse>> to the genitive.", "language": "en", "pause_after_ms": 900}, {"text": "That's all for today. See you in the next lesson, <<head aega>>.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Surface Cases: -le, -l, -lt</b>

The outer local cases answer <i>kuhu? kus? kust?</i> for surfaces: onto, on, off. They are also used for people, for activities such as work, and for "having".

📌 All three go on the genitive stem:
<code>laud → lauale → laual → laualt</code>
<code>töö → tööle → tööl → töölt</code>

💬 <i>Pane raamat lauale.</i> — Put the book on the table.
💬 <i>Raamat on laual.</i> — The book is on the table.
💬 <i>Võta raamat laualt.</i> — Take the book off the table.
💬 <i>Ma lähen tööle.</i> — I am going to work.
💬 <i>Ma helistan emale.</i> — I am calling my mother.

⚠️ Like English, Estonian separates "on" and "in": <i>laual</i> (on the table) but <i>majas</i> (in the house). Mixing them changes the meaning: <i>Raamat on lauas</i> would mean the book is inside the table.

💡 The adessive also expresses "to have": <i>Mul on auto.</i> — I have a car (literally: at me is a car).$c$ WHERE id = 'a2-allative-adessive-ablative';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-allative-adessive-ablative', 'en', $s$[{"text": "Hello. Today we learn the surface cases. These three cases describe moving onto something, being on it, and coming off it.", "language": "en", "pause_after_ms": 900}, {"text": "For onto we use <<le>>, for on we use <<l>>, and for off we use <<lt>>. The questions are again <<kuhu>>, <<kus>> and <<kust>>.", "language": "en", "pause_after_ms": 1000}, {"text": "The endings go on the genitive stem. The genitive of <<laud>> is <<laua>>, so we say <<lauale>>, <<laual>> and <<laualt>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Pane raamat lauale.", "language": "et", "pause_after_ms": 2400}, {"text": "Put the book on the table. There is movement, so we use the ending <<le>>.", "language": "en", "pause_after_ms": 900}, {"text": "Raamat on laual.", "language": "et", "pause_after_ms": 2400}, {"text": "The book is on the table. There is no movement here, just the ending <<l>>.", "language": "en", "pause_after_ms": 900}, {"text": "Võta raamat laualt.", "language": "et", "pause_after_ms": 2400}, {"text": "Take the book off the table. Leaving a surface is shown with the ending <<lt>>.", "language": "en", "pause_after_ms": 900}, {"text": "These cases are not only for surfaces. They are also used for activities like work, and for people.", "language": "en", "pause_after_ms": 900}, {"text": "Ma lähen tööle.", "language": "et", "pause_after_ms": 2400}, {"text": "I am going to work. For at work we say <<tööl>>, and for from work we say <<töölt>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma helistan emale.", "language": "et", "pause_after_ms": 2400}, {"text": "I am calling my mother. Movement towards a person also uses the ending <<le>>.", "language": "en", "pause_after_ms": 900}, {"text": "Mul on auto.", "language": "et", "pause_after_ms": 2400}, {"text": "I have a car. Having is also shown with the ending <<l>>. Word for word, it means at me is a car.", "language": "en", "pause_after_ms": 1000}, {"text": "Keep on and in apart, just as in English. For on the table we say <<laual>>, but for in the house we say <<majas>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now it's your turn. Say the phone is on the table in Estonian. Phone is also <<telefon>> in Estonian.", "language": "en", "pause_after_ms": 3800}, {"text": "Telefon on laual.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. There is no movement, so we used <<laual>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up, for surfaces we use the endings <<le>>, <<l>> and <<lt>>. The same endings work for work, for people and for having.", "language": "en", "pause_after_ms": 900}, {"text": "That's all for today. See you in the next lesson, <<head aega>>.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Simple Past (lihtminevik)</b>
The simple past tells what happened at a finished time: yesterday, last week.

📌 Most verbs: stem + <code>-si-</code> + ending (<code>ta</code> gets only <code>-s</code>): <code>ma elasin, sa elasid, ta elas, me elasime, te elasite, nad elasid</code>
📌 Some common verbs take <code>-i-</code> (and <code>ta</code> has no ending): <code>tulema → tulin, ta tuli</code>, <code>tegema → tegin, ta tegi</code>, <code>sööma → sõin, ta sõi</code>. Stem change: <code>minema → läksin, ta läks</code>
📌 Negative: <code>ei</code> + <code>-nud</code> form for all persons: <code>ma ei elanud</code>

💬 <i>Ma elasin kaks aastat Tartus.</i> — I lived in Tartu for two years.
💬 <i>Eile õppisime eesti keelt.</i> — Yesterday we studied Estonian.
💬 <i>Ta luges õhtul raamatut.</i> — In the evening she was reading a book.
💬 <i>Ma ei läinud eile tööle.</i> — I didn't go to work yesterday.

⚠️ The negative never changes for the person, just like English "didn't go": <i>ma ei läinud</i>, never <i>ma ei läksin</i>.
💡 <code>-si-</code> is the past marker, like English "-ed": <i>ela-si-n</i> = <i>I live-d</i>.$c$ WHERE id = 'a2-past-simple';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-past-simple', 'en', $s$[{"text": "Hello. Today we study the simple past tense in Estonian, <<lihtminevik>>. You need it to tell people what you did yesterday.", "language": "en", "pause_after_ms": 1000}, {"text": "The rule is simple. Drop the <<ma>> ending from the verb, then add <<si>> and the person ending to the stem. You can think of <<si>> a bit like the English ending ed.", "language": "en", "pause_after_ms": 1000}, {"text": "For example, <<elama>> means to live. <<ma elasin>>, <<sa elasid>>, <<ta elas>>. For he or she, only <<s>> remains.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma elasin kaks aastat Tartus.", "language": "et", "pause_after_ms": 2400}, {"text": "I lived in <<Tartu>> for two years. In <<elasin>> you hear <<si>> first, and then the person ending <<n>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Eile õppisime eesti keelt.", "language": "et", "pause_after_ms": 2400}, {"text": "Yesterday we studied Estonian. <<õppima>> became <<õppisime>>. First comes <<si>>, then <<me>> for we.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta luges õhtul raamatut.", "language": "et", "pause_after_ms": 2400}, {"text": "In the evening she was reading a book. <<lugema>> gives <<luges>>. The partitive object <<raamatut>> doesn't say whether she finished the book.", "language": "en", "pause_after_ms": 1000}, {"text": "Some very common verbs take <<i>> instead of <<si>>. <<sööma>> becomes <<sõin>>, and <<tegema>> becomes <<tegin>>. <<minema>> changes its stem and becomes <<läksin>>, a bit like go and went.", "language": "en", "pause_after_ms": 1000}, {"text": "Me sõime restoranis kala.", "language": "et", "pause_after_ms": 2400}, {"text": "We ate fish at the restaurant. <<sööma>> becomes <<sõime>> in the past, and the vowel in the stem changes too.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma tulin koju kell kuus.", "language": "et", "pause_after_ms": 2400}, {"text": "I came home at six o'clock. <<tulema>> also takes <<i>> and becomes <<tulin>>. For he or she there is no ending, we say <<ta tuli>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now let's move on to the negative. After <<ei>> comes the <<nud>> form of the verb, and it is the same for every person.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ei läinud eile tööle.", "language": "et", "pause_after_ms": 2400}, {"text": "I didn't go to work yesterday. Just like English I didn't go, you didn't go, we say <<ma ei läinud>>, <<sa ei läinud>>. <<ei läksin>> is wrong.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. Say in Estonian, yesterday evening I watched a film. Hint, to watch is <<vaatama>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Eile õhtul vaatasin filmi.", "language": "et", "pause_after_ms": 2400}, {"text": "That's right. <<vaatama>> becomes <<vaatasin>>. The time expression comes first, so the verb follows right after it.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, most verbs use the stem, then <<si>>, then the person ending. In the negative, we use <<ei>> and the <<nud>> form.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson, goodbye.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Frequency expressions: how often?</b>
Use these words to talk about habits and routines.

🔹 <code>iga päev</code> every day · <code>tavaliselt</code> usually · <code>sageli</code> / <code>tihti</code> often
🔹 <code>mõnikord</code> / <code>vahel</code> sometimes · <code>harva</code> rarely · <code>ei ... kunagi</code> never
🔹 Regular times with <code>-ti</code>: <code>hommik → hommikuti</code>, <code>esmaspäev → esmaspäeviti</code>
🔹 <code>kord nädalas</code> once a week, <code>kaks korda</code> twice

💬 <i>Ma käin iga päev tööl.</i> — I go to work every day.
💬 <i>Tavaliselt ärkan ma kell seitse.</i> — I usually wake up at seven.
💬 <i>Hommikuti joon ma kohvi.</i> — In the mornings I drink coffee.
💬 <i>Ma käin kaks korda nädalas ujumas.</i> — I go swimming twice a week.
💬 <i>Ta ei hiline kunagi.</i> — She is never late.

⚠️ When a frequency word starts the sentence, the verb usually comes second, before the subject: <i>Tavaliselt ärkan ma</i>. English keeps the subject first ("Usually I wake up"), so watch the order.
💡 Never = <code>ei</code> + <code>kunagi</code>: Estonian needs both, unlike English, where one "never" is enough. Without a verb, say <code>mitte kunagi</code>.$c$ WHERE id = 'a2-frequency';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-frequency', 'en', $s$[{"text": "Hello. Today we learn how to say how often we do something. These words are very useful when you talk about your daily habits.", "language": "en", "pause_after_ms": 1000}, {"text": "Here are the most important ones. <<iga päev>> means every day, <<tavaliselt>> usually, <<sageli>> often, <<mõnikord>> sometimes, and <<harva>> rarely.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma käin iga päev tööl.", "language": "et", "pause_after_ms": 2400}, {"text": "I go to work every day. <<iga päev>> is two words, and it can come after the verb.", "language": "en", "pause_after_ms": 1000}, {"text": "There is one rule. If the sentence starts with a frequency word, the verb usually moves to second place.", "language": "en", "pause_after_ms": 1000}, {"text": "Tavaliselt ärkan ma kell seitse.", "language": "et", "pause_after_ms": 2400}, {"text": "I usually wake up at seven. <<tavaliselt>> comes first, so the verb <<ärkan>> follows right after it, before <<ma>>. English would keep I first.", "language": "en", "pause_after_ms": 1000}, {"text": "Me sööme harva väljas.", "language": "et", "pause_after_ms": 2400}, {"text": "We rarely eat out. Here <<harva>> comes after the verb, while English puts rarely before the verb.", "language": "en", "pause_after_ms": 1000}, {"text": "For regular times, we use the ending <<ti>>. <<hommik>> means morning, and <<hommikuti>> means in the mornings.", "language": "en", "pause_after_ms": 1000}, {"text": "Hommikuti joon ma kohvi.", "language": "et", "pause_after_ms": 2400}, {"text": "In the mornings I drink coffee. Here too, the verb is in second place.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma käin kaks korda nädalas ujumas.", "language": "et", "pause_after_ms": 2400}, {"text": "I go swimming twice a week. <<korda>> means times, and <<nädalas>> means a week.", "language": "en", "pause_after_ms": 1000}, {"text": "To say never, you use the negative <<ei>> together with <<kunagi>>. In English one never is enough, but Estonian needs both.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta ei hiline kunagi.", "language": "et", "pause_after_ms": 2400}, {"text": "She is never late. On its own, <<kunagi>> means at some time. For the meaning never, you need a negative verb.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say sometimes I watch a film in the evening, and start with <<mõnikord>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Mõnikord vaatan ma õhtul filmi.", "language": "et", "pause_after_ms": 2400}, {"text": "Sometimes I watch a film in the evening. <<mõnikord>> is first, and the verb <<vaatan>> is in second place.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, if a frequency word comes first, the verb usually comes second. For never, use <<ei>> and <<kunagi>> together.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Consonant gradation (astmevaheldus)</b>
In many words the middle consonant changes between forms. The dictionary form has the strong grade; the genitive and the cases built on it (<code>-s</code>, <code>-st</code>, <code>-l</code>...) often have the weak grade.

🔹 Double → single: <code>kott → koti</code>, <code>lipp → lipu</code>, <code>tükk → tüki</code>
🔹 Hard → soft: <code>pank → panga</code>, <code>park → pargi</code>, <code>pilt → pildi</code>
🔹 Verbs too: <code>õppima → (ma) õpin</code>
🔹 The partitive usually keeps the strong grade: <code>kotti</code>, <code>parki</code>

💬 <i>Raamat on kotis.</i> — The book is in the bag.
💬 <i>Ma olen praegu pangas.</i> — I'm at the bank right now.
💬 <i>Lapsed mängivad pargis.</i> — The children are playing in the park.
💬 <i>Sinine on Eesti lipu värv.</i> — Blue is a colour of the Estonian flag.
💬 <i>Ma õpin eesti keelt.</i> — I'm learning Estonian.

⚠️ Don't add endings to the dictionary form: <i>parkis</i> ✗ → <i>pargis</i> ✓. Not every word changes: <code>maja → majas</code>.
💡 English has nothing like this, so you can't guess it from the dictionary form. Learn each new noun together with its genitive: <code>pank → panga</code>, then build the other cases on that.$c$ WHERE id = 'a2-consonant-gradation';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-consonant-gradation', 'en', $s$[{"text": "Hello. Today we learn one of the most typical features of Estonian, consonant gradation. You need it to put endings on words correctly.", "language": "en", "pause_after_ms": 1000}, {"text": "The dictionary form has the strong grade. In the genitive and the cases built on it, the middle consonant often gets weaker. The partitive usually stays strong.", "language": "en", "pause_after_ms": 1000}, {"text": "The first type is a double consonant becoming single. <<kott>> means bag, and its genitive is <<koti>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Raamat on kotis.", "language": "et", "pause_after_ms": 2400}, {"text": "The book is in the bag. In <<kotis>> there is one <<t>> instead of two.", "language": "en", "pause_after_ms": 1000}, {"text": "Sinine on Eesti lipu värv.", "language": "et", "pause_after_ms": 2400}, {"text": "Blue is a colour of the Estonian flag. The word <<lipp>> became <<lipu>> here.", "language": "en", "pause_after_ms": 1000}, {"text": "The second type is a hard consonant becoming soft. A <<k>> can turn into a <<g>>, a <<t>> into a <<d>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma olen praegu pangas.", "language": "et", "pause_after_ms": 2400}, {"text": "I'm at the bank right now. The <<k>> in <<pank>> softened, and we get <<pangas>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Lapsed mängivad pargis.", "language": "et", "pause_after_ms": 2400}, {"text": "The children are playing in the park. The word <<park>> works the same way and becomes <<pargis>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Verbs do the same. The present tense of <<õppima>> is <<õpin>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma õpin eesti keelt.", "language": "et", "pause_after_ms": 2400}, {"text": "I'm learning Estonian. The double <<p>> became a single one here.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is adding the ending to the dictionary form. <<parkis>> is wrong, the right form is <<pargis>>. But not every word changes, <<maja>> simply becomes <<majas>>.", "language": "en", "pause_after_ms": 1100}, {"text": "Now you try. <<pilt>> means picture, and <<meri>> means sea. For on the picture, use the ending <<l>>. Say: there is a sea in the picture.", "language": "en", "pause_after_ms": 3800}, {"text": "Pildil on meri.", "language": "et", "pause_after_ms": 2400}, {"text": "The <<t>> in <<pilt>> softened, and we get <<pildil>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, double consonants become single, hard ones become soft, and endings like <<s>>, <<st>> and <<l>> go on the weak form. Learn new words together with their genitive.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Comparatives and Superlatives</b>

Use the comparative to compare two things and the superlative for "the most".

📌 Comparative: genitive stem + <code>-m</code>
<code>suur → suure → suurem</code> bigger
<code>ilus → ilusa → ilusam</code> more beautiful
📌 Two-syllable stems in <code>-a</code> usually change it to <code>-e</code>: <code>vana → vanem</code>, <code>pikk → pikem</code>
📌 Superlative: <code>kõige</code> + comparative: <code>kõige suurem</code>
📌 Irregular: <code>hea → parem → kõige parem</code>

💬 <i>Tallinn on suurem kui Tartu.</i> — Tallinn is bigger than Tartu.
💬 <i>Minu vend on minust vanem.</i> — My brother is older than me.
💬 <i>Täna on ilm parem kui eile.</i> — The weather is better today than yesterday.
💬 <i>See on kõige ilusam linn.</i> — This is the most beautiful city.

⚠️ Two ways to say "than": <i>kui</i> + the same case as the compared word, usually the nominative (<i>suurem kui Tartu</i>) or the elative without <i>kui</i> (<i>Tartust suurem</i>). Do not mix them: never <i>kui Tartust</i>.

💡 With the elative, the case ending does the job of English "than": <i>Tartust suurem</i> = bigger than Tartu (literally "from Tartu bigger").$c$ WHERE id = 'a2-comparatives';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-comparatives', 'en', $s$[{"text": "Hello. Today we learn comparatives and superlatives. Saying bigger, cheaper or the most beautiful comes up all the time in everyday speech.", "language": "en", "pause_after_ms": 900}, {"text": "To make the comparative, add <<m>> to the genitive of the adjective. The genitive of <<suur>> is <<suure>>, so bigger is <<suurem>>.", "language": "en", "pause_after_ms": 1000}, {"text": "For the superlative, put <<kõige>> in front. <<kõige suurem>> means the biggest.", "language": "en", "pause_after_ms": 900}, {"text": "Tallinn on suurem kui Tartu.", "language": "et", "pause_after_ms": 2400}, {"text": "Tallinn is bigger than Tartu. After <<kui>>, which means than, the noun stays in the nominative.", "language": "en", "pause_after_ms": 900}, {"text": "Tallinn on Tartust suurem.", "language": "et", "pause_after_ms": 2400}, {"text": "Same meaning. This time there is no <<kui>>, and <<Tartu>> is in the elative case. The ending <<st>> does the work of the English word than.", "language": "en", "pause_after_ms": 1000}, {"text": "In two-syllable words ending in <<a>>, that sound usually becomes <<e>>. <<vana>> means old, and older is <<vanem>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Minu vend on minust vanem.", "language": "et", "pause_after_ms": 2400}, {"text": "My brother is older than me. <<minust>> means than me, again in the elative.", "language": "en", "pause_after_ms": 900}, {"text": "Täna on ilm parem kui eile.", "language": "et", "pause_after_ms": 2400}, {"text": "The weather is better today than yesterday. <<hea>> is irregular, and better is <<parem>>.", "language": "en", "pause_after_ms": 900}, {"text": "See on kõige ilusam linn.", "language": "et", "pause_after_ms": 2400}, {"text": "This is the most beautiful city. From <<ilus>> we made <<ilusam>>, with <<kõige>> in front.", "language": "en", "pause_after_ms": 900}, {"text": "A common mistake is mixing the two patterns. <<kui Tartust>> is wrong. Say either <<kui Tartu>> or just <<Tartust>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now it's your turn. Say in Estonian: this coffee is cheaper. Cheap is <<odav>>.", "language": "en", "pause_after_ms": 3800}, {"text": "See kohv on odavam.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The genitive of <<odav>> is <<odava>>, and adding <<m>> gives <<odavam>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up, add <<m>> to the genitive, use <<kõige>> for the superlative, and for than use either <<kui>> or the elative.", "language": "en", "pause_after_ms": 900}, {"text": "That's all for today. See you in the next lesson, <<head aega>>.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Expressing Obligation (peab, tuleb, on vaja)</b>
Estonian has three common ways to say must, have to or need to.

📌 <code>pidama</code> + <code>-ma</code>, conjugated: <code>ma pean, sa pead, ta peab, me peame, te peate, nad peavad</code>
📌 <code>mul on vaja</code> + <code>-da</code>: I need to (also + noun: <code>mul on vaja uut telefoni</code>)
📌 <code>tuleb</code> + <code>-da</code>: rules, instructions; person with <code>-l</code>: <code>mul tuleb</code>
📌 No need: <code>ei pea</code> + <code>-ma</code>. Not allowed: <code>ei tohi</code> + <code>-da</code>

💬 <i>Ma pean täna kaua töötama.</i> — I have to work long hours today.
💬 <i>Mul on vaja arsti juurde minna.</i> — I need to go to the doctor.
💬 <i>Enne sööki tuleb käsi pesta.</i> — You have to wash your hands before eating.
💬 <i>Sa ei pea homme tulema.</i> — You don't have to come tomorrow.
💬 <i>Siin ei tohi suitsetada.</i> — Smoking is not allowed here.

⚠️ English "must not" and "don't have to" are easy to mix up. Estonian keeps them apart: <i>sa ei pea minema</i> = you don't have to go, but <i>sa ei tohi minna</i> = you mustn't go.
💡 <i>pean</i> + ma; <i>tuleb, vaja, tohi</i> + da.$c$ WHERE id = 'a2-obligation';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-obligation', 'en', $s$[{"text": "Hello. Today we learn how to express obligation in Estonian. There are a few basic patterns for saying that something is necessary, not necessary, or not allowed.", "language": "en", "pause_after_ms": 1000}, {"text": "The first is the verb <<pidama>>. It changes with the person, <<ma pean>>, <<sa pead>>, <<ta peab>>, and it is followed by the <<ma>> infinitive.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma pean täna kaua töötama.", "language": "et", "pause_after_ms": 2400}, {"text": "I have to work long hours today. After <<pean>> comes <<töötama>>, the <<ma>> infinitive.", "language": "en", "pause_after_ms": 1000}, {"text": "The second is <<on vaja>>, meaning it is needed. The person comes first as <<mul>>, <<sul>> or <<tal>>, and then the <<da>> infinitive.", "language": "en", "pause_after_ms": 1000}, {"text": "Mul on vaja arsti juurde minna.", "language": "et", "pause_after_ms": 2400}, {"text": "I need to go to the doctor. The verb <<minema>> takes the form <<minna>> here.", "language": "en", "pause_after_ms": 1000}, {"text": "The third is <<tuleb>>. It is used for rules and instructions, it sounds a little more formal, and it also takes the <<da>> infinitive.", "language": "en", "pause_after_ms": 1000}, {"text": "Enne sööki tuleb käsi pesta.", "language": "et", "pause_after_ms": 2400}, {"text": "You have to wash your hands before eating. There is no particular person, it's a general rule.", "language": "en", "pause_after_ms": 1000}, {"text": "Mul tuleb homme vara tõusta.", "language": "et", "pause_after_ms": 2400}, {"text": "I have to get up early tomorrow. To name the person, we put <<mul>> at the start.", "language": "en", "pause_after_ms": 1000}, {"text": "Now let's look at negative sentences, because there is an important difference here.", "language": "en", "pause_after_ms": 800}, {"text": "Sa ei pea homme tulema.", "language": "et", "pause_after_ms": 2400}, {"text": "You don't have to come tomorrow. <<ei pea>> means there is no need. It does not mean forbidden.", "language": "en", "pause_after_ms": 1000}, {"text": "Siin ei tohi suitsetada.", "language": "et", "pause_after_ms": 2400}, {"text": "Smoking is not allowed here. <<ei tohi>> means forbidden. To say you mustn't go, use <<sa ei tohi minna>>, not <<sa ei pea minema>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. Say in Estonian: I don't have to go to the shop today. Hint, to the shop is <<poodi>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma ei pea täna poodi minema.", "language": "et", "pause_after_ms": 2400}, {"text": "That's right. There is no obligation, so we use <<ei pea>> followed by the <<ma>> infinitive, <<minema>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, <<pidama>> takes the <<ma>> infinitive. <<on vaja>>, <<tuleb>> and <<ei tohi>> take the <<da>> infinitive.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson, goodbye.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>ma-infinitive vs da-infinitive</b>
At A1 you met <i>lähen + ma</i> and <i>tahan + da</i>. Now: which verbs need which form, and how to build the da-form.

📌 <code>-ma</code> after <code>hakkama</code> (start), <code>jääma</code> (stay), <code>pidama</code> (must) and verbs of motion: <code>minema, tulema</code>
📌 <code>-da</code> after <code>tahtma, võima, oskama, proovima, armastama</code>, <code>meeldib</code>, <code>on vaja</code>
📌 Regular: <code>õppima → õppida</code>, <code>rääkima → rääkida</code>
📌 Learn by heart: <code>tulla, minna, olla, süüa, teha</code>

💬 <i>Lapsed jäid koju mängima.</i> — The children stayed home to play.
💬 <i>Ma proovin homme vara tõusta.</i> — I'll try to get up early tomorrow.
💬 <i>Mulle meeldib eesti keelt rääkida.</i> — I like speaking Estonian.
💬 <i>Ma ei oska autot juhtida.</i> — I can't drive a car.

⚠️ English uses "to" for both forms, so it can't tell you which one to pick. <code>pidama</code> is the classic trap: "I have to go" sounds like the da-group, but Estonian needs <code>-ma</code>: <i>Ma pean minema</i>, not <i>Ma pean minna</i>.
💡 Learn verbs in pairs: <i>jään ootama</i>, <i>proovin teha</i>, <i>pean minema</i>.$c$ WHERE id = 'a2-ma-da-infinitive';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-ma-da-infinitive', 'en', $s$[{"text": "Hello. Today we take the <<ma>> and <<da>> infinitives one step further. We'll see which verbs take which form, and how to build the <<da>> form.", "language": "en", "pause_after_ms": 1000}, {"text": "In English, both forms are usually translated with to, so English can't tell you which one to choose. That's why it pays to learn verbs together with their partner form.", "language": "en", "pause_after_ms": 1000}, {"text": "The <<ma>> infinitive comes after <<hakkama>>, to start, <<jääma>>, to stay, <<pidama>>, to have to, and after verbs of going and coming.", "language": "en", "pause_after_ms": 1000}, {"text": "Vihma hakkas sadama.", "language": "et", "pause_after_ms": 2400}, {"text": "It started to rain. After <<hakkama>> you always get the <<ma>> infinitive, here <<sadama>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Lapsed jäid koju mängima.", "language": "et", "pause_after_ms": 2400}, {"text": "The children stayed home to play. <<jääma>> also takes the <<ma>> infinitive.", "language": "en", "pause_after_ms": 1000}, {"text": "The <<da>> infinitive comes after verbs of wanting, permission and ability, such as <<tahtma>>, <<võima>> and <<oskama>>, and also after <<meeldib>> and <<on vaja>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma proovin homme vara tõusta.", "language": "et", "pause_after_ms": 2400}, {"text": "I'll try to get up early tomorrow. After <<proovima>> comes the <<da>> infinitive, so <<tõusma>> becomes <<tõusta>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Mulle meeldib eesti keelt rääkida.", "language": "et", "pause_after_ms": 2400}, {"text": "I like speaking Estonian. In <<rääkima>> we replace <<ma>> with <<da>> and get <<rääkida>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ei oska autot juhtida.", "language": "et", "pause_after_ms": 2400}, {"text": "I can't drive a car. <<oskama>> is about ability, so it takes <<juhtida>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Some common verbs have an irregular <<da>> form. <<minema>> becomes <<minna>>, <<tulema>> becomes <<tulla>>, and <<sööma>> becomes <<süüa>>. Learn these by heart.", "language": "en", "pause_after_ms": 1000}, {"text": "Here is the most common mistake. <<pidama>> expresses obligation, but it takes the <<ma>> infinitive, not the <<da>> one.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma pean nüüd minema.", "language": "et", "pause_after_ms": 2400}, {"text": "I have to go now. Saying <<ma pean minna>> is wrong, the correct form is <<ma pean minema>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. Say in Estonian: I want to go to the cinema. Hint, to want is <<tahtma>>, and to the cinema is <<kinno>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma tahan kinno minna.", "language": "et", "pause_after_ms": 2400}, {"text": "That's right. <<tahtma>> takes the <<da>> infinitive, and <<minema>> becomes the irregular <<minna>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, use <<ma>> after starting, staying, having to, going and coming. Use <<da>> after wanting, permission, ability and liking.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson, goodbye.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Postpositions — after the noun</b>

Place words such as "in front of" or "under" come AFTER a noun in the genitive, the opposite of English: <i>maja ees</i> is literally "house in front of".

📌 Most place postpositions have three forms: where to? → where? → from where?
<code>ette → ees → eest</code> in front of
<code>taha → taga → tagant</code> behind
<code>alla → all → alt</code> under
<code>peale → peal → pealt</code> on top of
<code>kõrvale → kõrval → kõrvalt</code> next to

💬 <i>Auto on maja ees.</i> — The car is in front of the house.
💬 <i>Kass istub laua all.</i> — The cat is sitting under the table.
💬 <i>Kass läheb laua alla.</i> — The cat goes under the table.
💬 <i>Pood on panga kõrval.</i> — The shop is next to the bank.
💬 <i>Ma ootan sind kino ees.</i> — I will wait for you in front of the cinema.

⚠️ The noun must be in the genitive: <i>laua all</i>, not <i>laud all</i>. With movement use the where-to form: <i>läheb laua alla</i>, not <i>laua all</i>.

💡 English often uses one word for both place and movement ("under the table"). Estonian always shows the difference: <code>alla → all → alt</code> = (to) under, under, from under.$c$ WHERE id = 'a2-postpositions';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-postpositions', 'en', $s$[{"text": "Hello. Today we learn Estonian postpositions, the words for places like in front of and under. In English these words come before the noun. In Estonian they come after it.", "language": "en", "pause_after_ms": 900}, {"text": "First comes the noun in the genitive, then the postposition. <<maja ees>> means in front of the house, literally house in front of.", "language": "en", "pause_after_ms": 1000}, {"text": "Most place postpositions have three forms. For where to, we say <<alla>>. For where, <<all>>. For where from, <<alt>>. In English that's to under, under, and from under.", "language": "en", "pause_after_ms": 1000}, {"text": "Auto on maja ees.", "language": "et", "pause_after_ms": 2400}, {"text": "The car is in front of the house. <<maja>> is in the genitive here, and it looks the same as the dictionary form. <<ees>> means in front of.", "language": "en", "pause_after_ms": 900}, {"text": "Kass istub laua all.", "language": "et", "pause_after_ms": 2400}, {"text": "The cat is sitting under the table. In the genitive, <<laud>> becomes <<laua>>.", "language": "en", "pause_after_ms": 900}, {"text": "Kass läheb laua alla.", "language": "et", "pause_after_ms": 2400}, {"text": "The cat goes under the table. There is movement, so we use the where to form, <<alla>>. English just says under for both.", "language": "en", "pause_after_ms": 900}, {"text": "Pood on panga kõrval.", "language": "et", "pause_after_ms": 2400}, {"text": "The shop is next to the bank. The genitive of <<pank>> is <<panga>>.", "language": "en", "pause_after_ms": 900}, {"text": "Koer on maja taga.", "language": "et", "pause_after_ms": 2400}, {"text": "The dog is behind the house. For going behind, say <<taha>>. For coming from behind, say <<tagant>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma ootan sind kino ees.", "language": "et", "pause_after_ms": 2400}, {"text": "I will wait for you in front of the cinema. This pattern is very handy for arranging where to meet.", "language": "en", "pause_after_ms": 900}, {"text": "The most common mistake is leaving the noun in the nominative. <<laud all>> is wrong, the correct form is <<laua all>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now it's your turn. Say in Estonian: the book is on the table. The word for on top of is <<peal>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Raamat on laua peal.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. First the genitive <<laua>>, then <<peal>>. You can also say it more briefly as <<laual>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up, the noun goes in the genitive, the postposition comes after it, and it has separate forms for where to, where, and where from.", "language": "en", "pause_after_ms": 900}, {"text": "That's all for today. See you in the next lesson, <<head aega>>.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Present Perfect (täisminevik)</b>
It links a past action to the present: life experience, a result that matters now, or a period not yet over (today).

📌 Form: <code>olema</code> in the present + <code>-nud</code> form: <code>ma olen, sa oled, ta on, me oleme, te olete, nad on söönud</code>
📌 <code>-nud</code>: <code>elama → elanud</code>, but <code>tegema → teinud</code>, <code>nägema → näinud</code>, <code>minema → läinud</code>
📌 Negative: <code>ei ole</code> (or <code>pole</code>) + <code>-nud</code>: <code>ma ei ole söönud</code>

💬 <i>Kas sa oled kunagi Tartus käinud?</i> — Have you ever been to Tartu?
💬 <i>Ma olen juba söönud.</i> — I have already eaten.
💬 <i>Ma olen oma võtmed ära kaotanud.</i> — I have lost my keys.
💬 <i>Me ei ole seda filmi veel näinud.</i> — We haven't seen this film yet.

⚠️ <i>olen ... -nud</i> is built and used much like English "have ... -ed". As in English, a finished time such as <i>eile</i> calls for the simple past: <i>Ma sõin eile kala</i>.
💡 <i>juba, veel, kunagi, täna</i> usually → perfect; <i>eile, möödunud aastal</i> → simple past.$c$ WHERE id = 'a2-present-perfect';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-present-perfect', 'en', $s$[{"text": "Hello. Today we study <<täisminevik>>, the present perfect, the tense that links the past to the present. It's very useful for talking about experiences and things you've just done.", "language": "en", "pause_after_ms": 1000}, {"text": "Here's how it's built: the present tense of <<olema>>, so <<olen>>, <<oled>>, <<on>>, followed by the <<nud>> form of the main verb. It's a lot like English have plus eaten.", "language": "en", "pause_after_ms": 1000}, {"text": "For most verbs, drop <<ma>> and add <<nud>>. <<elama>> gives <<elanud>>, <<käima>> gives <<käinud>>, but <<tegema>> gives <<teinud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Kas sa oled kunagi Tartus käinud?", "language": "et", "pause_after_ms": 2400}, {"text": "Have you ever been to Tartu? We're asking about life experience. <<kunagi>> means ever here.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma olen juba söönud.", "language": "et", "pause_after_ms": 2400}, {"text": "I have already eaten. The result matters now, I'm not hungry. <<juba>> means already.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta on täna palju töötanud.", "language": "et", "pause_after_ms": 2400}, {"text": "She has worked a lot today. Today isn't over yet, so we use <<täisminevik>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma olen oma võtmed ära kaotanud.", "language": "et", "pause_after_ms": 2400}, {"text": "I have lost my keys. The result matters now, because the keys are still missing.", "language": "en", "pause_after_ms": 1000}, {"text": "To make it negative, use <<ei ole>> or the short form <<pole>>. The <<nud>> form doesn't change.", "language": "en", "pause_after_ms": 1000}, {"text": "Me ei ole seda filmi veel näinud.", "language": "et", "pause_after_ms": 2400}, {"text": "We haven't seen this film yet. <<veel>> means yet, and it's very common in negative sentences.", "language": "en", "pause_after_ms": 1000}, {"text": "Careful. Just as in English, a finished time like yesterday usually goes with the simple past, not the perfect.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma sõin eile kala.", "language": "et", "pause_after_ms": 2400}, {"text": "I ate fish yesterday. Yesterday is over, so the simple past sounds more natural here than <<ma olen eile kala söönud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. Say in Estonian: I haven't read this book yet. Hint, to read is <<lugema>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma ei ole seda raamatut veel lugenud.", "language": "et", "pause_after_ms": 2400}, {"text": "That's right. <<lugema>> gives <<lugenud>>. In a negative sentence the object is in the partitive, <<seda raamatut>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, <<olema>> plus the <<nud>> form connects the past to the present. <<juba>>, <<veel>> and <<kunagi>> are typical signals of this tense.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson, goodbye.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Reflexive pronoun: end / ennast and ise</b>
When the action goes back to the subject, Estonian uses <code>end</code> or <code>ennast</code>. To stress that someone does it personally, use <code>ise</code>.

🔹 <code>end</code> and <code>ennast</code> are both partitive forms of <code>ise</code> and mean the same; <code>end</code> is shorter and very common
🔹 It never changes with the person: <code>ma pesen end, sa pesed end, me peseme end</code>
🔹 <code>ise</code> emphasises the doer: <code>ma teen seda ise</code>
🔹 Some verbs have an <code>-u-</code> reflexive form: <code>riietama</code> (dress someone) → <code>riietuma</code> (get dressed)

💬 <i>Ma pesen end hommikul.</i> — I wash in the morning.
💬 <i>Ta vaatab end peeglist.</i> — She looks at herself in the mirror.
💬 <i>Palun tutvusta ennast.</i> — Please introduce yourself.
💬 <i>Ma tunnen end täna hästi.</i> — I feel good today.
💬 <i>Ma teen seda ise.</i> — I'm doing it myself.

⚠️ English changes the pronoun (myself, yourself, ourselves), Estonian does not. Not <i>Ma pesen mind</i>, but <i>Ma pesen end</i>. And where English drops "myself" (I wash, I feel good), Estonian still needs <code>end</code>.
💡 Object of the action → <code>end</code>; stressing who does it → <code>ise</code>.$c$ WHERE id = 'a2-reflexive-verbs';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('a2-reflexive-verbs', 'en', $s$[{"text": "Hello. Today we learn the words <<end>> and <<ennast>>. Like English myself or yourself, they are used when the action goes back to the subject.", "language": "en", "pause_after_ms": 1000}, {"text": "The rule is simple. <<end>> and <<ennast>> are the same word, and they never change with the person. For I, you, she and we, it's always <<end>>, where English switches between myself, yourself and ourselves.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma pesen end hommikul.", "language": "et", "pause_after_ms": 2400}, {"text": "I wash in the morning. English often leaves out myself here, but Estonian needs <<end>> with <<pesema>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta vaatab end peeglist.", "language": "et", "pause_after_ms": 2400}, {"text": "She looks at herself in the mirror. The subject changed, but <<end>> stayed the same.", "language": "en", "pause_after_ms": 1000}, {"text": "Palun tutvusta ennast.", "language": "et", "pause_after_ms": 2400}, {"text": "Please introduce yourself. Here we have the longer form <<ennast>>, which means the same as <<end>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma tunnen end täna hästi.", "language": "et", "pause_after_ms": 2400}, {"text": "I feel good today. Together with <<end>>, the verb <<tundma>> means to feel.", "language": "en", "pause_after_ms": 1000}, {"text": "Now the base form of these words, <<ise>>. It isn't used as an object. It stresses who does the action, like myself in I did it myself.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma teen seda ise.", "language": "et", "pause_after_ms": 2400}, {"text": "I'm doing it myself. <<ise>> puts extra weight on the subject.", "language": "en", "pause_after_ms": 1000}, {"text": "Laps sööb juba ise.", "language": "et", "pause_after_ms": 2400}, {"text": "The child already eats by himself. <<ise>> shows he does it without help.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is using the normal object pronoun, like <<mind>>, because English says me or myself. The right word is always <<end>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say in Estonian: we introduce ourselves.", "language": "en", "pause_after_ms": 3800}, {"text": "Me tutvustame ennast.", "language": "et", "pause_after_ms": 2400}, {"text": "We introduce ourselves. Even though the subject is we, we still use <<ennast>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, use <<end>> or <<ennast>> as the object when the action goes back to the subject, and <<ise>> to stress who does it personally.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();

--changeset english-grammar-content:b1 splitStatements:false
UPDATE grammar_lessons SET content = $c$<b>Verb Rection: which case a verb needs</b>

Many Estonian verbs require a fixed case, and it is often not what English would suggest. Learn each verb with its question.

<code>aitama, tänama, kartma, ootama</code> + partitive
<code>helistama, vastama</code> + allative <code>-le</code>
<code>huvituma, rääkima, sõltuma</code> + elative <code>-st</code>

💬 <i>Ta aitab mind.</i> — He helps me. (partitive: mind)
💬 <i>Laps kardab koera.</i> — The child is afraid of the dog. (no "of": partitive koera)
💬 <i>Ma helistan emale.</i> — I'm calling my mum. (literally "to mum")
💬 <i>Ma huvitun muusikast.</i> — I'm interested in music. (English "in", Estonian -st)
💬 <i>See sõltub ilmast.</i> — It depends on the weather. (English "on", Estonian -st)

⚠️ Don't let English choose the case: not <i>Ma aitan sulle</i> but <i>Ma aitan sind</i>; not <i>Ma helistan ema</i> but <i>Ma helistan emale</i>. Partitive verbs keep the partitive even when the action is finished: <i>Ta tänas õpetajat</i>, not <i>õpetaja</i>.

💡 Write every new verb in your notebook with its question: <i>helistama kellele?</i>, <i>kartma keda?</i>, <i>huvituma millest?</i>$c$ WHERE id = 'b1-verb-rection';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-verb-rection', 'en', $s$[{"text": "Hello. Today we look at verb rection, which means the case that the noun after a verb has to take.", "language": "en", "pause_after_ms": 1000}, {"text": "This matters because Estonian verbs often want a different case from what English would suggest. So learn every verb together with its case.", "language": "en", "pause_after_ms": 1000}, {"text": "Some verbs always take the partitive. Among them are <<aitama>>, to help, <<tänama>>, to thank, <<kartma>>, to fear, and <<ootama>>, to wait.", "language": "en", "pause_after_ms": 900}, {"text": "Ta aitab mind.", "language": "et", "pause_after_ms": 2200}, {"text": "He helps me. The word for me is the partitive form <<mind>>.", "language": "en", "pause_after_ms": 900}, {"text": "Laps kardab koera.", "language": "et", "pause_after_ms": 2200}, {"text": "The child is afraid of the dog. English needs the word of, but Estonian simply uses the partitive <<koera>>.", "language": "en", "pause_after_ms": 900}, {"text": "Other verbs take the ending <<le>>, meaning to someone. Two of them are <<helistama>>, to call, and <<vastama>>, to answer.", "language": "en", "pause_after_ms": 900}, {"text": "Ma helistan emale.", "language": "et", "pause_after_ms": 2200}, {"text": "I'm calling my mum. In English mum is a direct object, but Estonian says <<emale>>, literally to mum.", "language": "en", "pause_after_ms": 900}, {"text": "Ma vastan õpetaja küsimusele.", "language": "et", "pause_after_ms": 2400}, {"text": "I'm answering the teacher's question. Estonian says literally: I answer to the teacher's question.", "language": "en", "pause_after_ms": 900}, {"text": "A third group takes the ending <<st>>, meaning from or about. These include <<huvituma>>, <<rääkima>> and <<sõltuma>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma huvitun muusikast.", "language": "et", "pause_after_ms": 2200}, {"text": "I'm interested in music. English says in, but Estonian says <<muusikast>>, literally from music.", "language": "en", "pause_after_ms": 900}, {"text": "See sõltub ilmast.", "language": "et", "pause_after_ms": 2200}, {"text": "It depends on the weather. English says on, but Estonian says <<ilmast>>.", "language": "en", "pause_after_ms": 900}, {"text": "One more common mistake. Partitive verbs keep the partitive even when the action is finished. Say <<Ta tänas õpetajat>>, not <<õpetaja>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. You want to thank a group of people, or one person politely. How do you say, I thank you?", "language": "en", "pause_after_ms": 3800}, {"text": "Ma tänan teid.", "language": "et", "pause_after_ms": 2200}, {"text": "Well done. In English you is just the object, but <<tänama>> needs the partitive, so you say <<teid>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, learn each new verb with its question, for example <<helistama kellele>> or <<kartma keda>>.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson. Goodbye.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Translative Case (-ks): becoming</b>

The translative shows a change of state: what someone or something becomes. The ending <code>-ks</code> is added to the genitive stem.

<code>arst → arsti → arstiks</code>
<code>suur → suure → suureks</code>
<code>külm → külma → külmaks</code>
Typical verbs: <code>saama, jääma, minema, muutuma</code>
Also a deadline or purpose: <code>homseks</code> (by tomorrow), <code>hommikusöögiks</code> (for breakfast)

💬 <i>Ta sai arstiks.</i> — He became a doctor.
💬 <i>Ma jäin haigeks.</i> — I fell ill.
💬 <i>Ilm läks külmaks.</i> — The weather turned cold.
💬 <i>Ma värvisin seina valgeks.</i> — I painted the wall white.
💬 <i>Ma teen töö homseks valmis.</i> — I'll have the work done by tomorrow.

⚠️ English says "became a doctor" with a bare noun, so learners write <i>Ta sai arst</i>. Estonian needs -ks: <i>Ta sai arstiks</i>. Don't confuse it with the essive -na: <i>Ta töötab arstina</i> = works as a doctor (a role, no change).

💡 The case answers <i>kelleks? milleks?</i> (into whom, into what). Remember: saama + -ks = to become.$c$ WHERE id = 'b1-translative-case';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-translative-case', 'en', $s$[{"text": "Hello. Today we learn the translative case. Estonian uses it when someone becomes a doctor, or when the weather turns cold.", "language": "en", "pause_after_ms": 1000}, {"text": "Here is the rule. Add the ending <<ks>> to the genitive stem. So <<arst>> becomes <<arsti>>, and then <<arstiks>>.", "language": "en", "pause_after_ms": 1000}, {"text": "This case usually comes with the verbs <<saama>>, <<jääma>>, <<minema>> and <<muutuma>>. They all describe some kind of change.", "language": "en", "pause_after_ms": 900}, {"text": "Ta sai arstiks.", "language": "et", "pause_after_ms": 2200}, {"text": "He became a doctor. In English the word doctor needs no ending, but in Estonian it must be <<arstiks>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma jäin haigeks.", "language": "et", "pause_after_ms": 2200}, {"text": "I fell ill. Here the verb <<jääma>> means falling into a state.", "language": "en", "pause_after_ms": 900}, {"text": "Ilm läks külmaks.", "language": "et", "pause_after_ms": 2200}, {"text": "The weather turned cold. Adjectives take the ending too: <<külm>> becomes <<külmaks>>.", "language": "en", "pause_after_ms": 900}, {"text": "Vesi muutus jääks.", "language": "et", "pause_after_ms": 2200}, {"text": "The water turned into ice. The verb <<muutuma>> describes a complete transformation.", "language": "en", "pause_after_ms": 900}, {"text": "Ma värvisin seina valgeks.", "language": "et", "pause_after_ms": 2400}, {"text": "I painted the wall white. When you put something into a new state, you also use <<ks>>, even where English just says white.", "language": "en", "pause_after_ms": 900}, {"text": "Ma teen töö homseks valmis.", "language": "et", "pause_after_ms": 2400}, {"text": "I'll have the work done by tomorrow. Here <<homseks>> means by tomorrow at the latest, so it sets a deadline.", "language": "en", "pause_after_ms": 900}, {"text": "A common mistake is mixing this case with the essive. <<töötab arstina>> means works as a doctor, and there is no change at all.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. My brother became a teacher. How would you say that in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Minu vend sai õpetajaks.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The word <<õpetaja>> took the ending <<ks>> and became <<õpetajaks>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, the ending <<ks>> shows a change and its result. For a role without any change, use the ending <<na>>.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson. Goodbye.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Terminative, Essive and Abessive</b>

Three cases that do the job of English prepositions, all attached to the genitive stem: <code>-ni</code> "up to, until", <code>-na</code> "as, in the role of", <code>-ta</code> "without".

<code>esmaspäev → esmaspäeva → esmaspäevani</code>
<code>laps → lapse → lapsena</code>
<code>suhkur → suhkru → suhkruta</code>
With verbs: <code>sööma → söömata</code> (without eating)

💬 <i>Ma ootan sind esmaspäevani.</i> — I'll wait for you until Monday.
💬 <i>Ta töötab õpetajana.</i> — She works as a teacher.
💬 <i>Lapsena elasin ma maal.</i> — As a child I lived in the countryside.
💬 <i>Ma joon kohvi suhkruta.</i> — I drink coffee without sugar.
💬 <i>Ma läksin kooli söömata.</i> — I went to school without eating.

⚠️ Don't mix the essive with the translative: <i>Ta töötab arstina</i> = works as a doctor (a role), but <i>Ta sai arstiks</i> = became a doctor (a change). English uses "as" and "became"; Estonian uses -na and -ks.

💡 You already know -ni from goodbyes: <i>Nägemiseni!</i> (until we see each other) and <i>Homseni!</i> (until tomorrow).$c$ WHERE id = 'b1-terminative-essive-abessive';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-terminative-essive-abessive', 'en', $s$[{"text": "Hello. Today we learn three short but very useful cases. They match the English words until, as, and without.", "language": "en", "pause_after_ms": 1000}, {"text": "All three endings attach to the genitive stem. For example, <<laps>> first becomes <<lapse>>, and the ending goes onto that stem.", "language": "en", "pause_after_ms": 1000}, {"text": "The first is the terminative, with the ending <<ni>>. It means until, or up to.", "language": "en", "pause_after_ms": 900}, {"text": "Ma ootan sind esmaspäevani.", "language": "et", "pause_after_ms": 2400}, {"text": "I'll wait for you until Monday. The ending <<ni>> sets the time limit.", "language": "en", "pause_after_ms": 900}, {"text": "Pood on lahti kella kaheksani.", "language": "et", "pause_after_ms": 2400}, {"text": "The shop is open until eight o'clock. Clock times use the same ending.", "language": "en", "pause_after_ms": 900}, {"text": "The second is the essive, with the ending <<na>>. It matches the English word as.", "language": "en", "pause_after_ms": 900}, {"text": "Ta töötab õpetajana.", "language": "et", "pause_after_ms": 2400}, {"text": "She works as a teacher. This describes a job, in other words a role.", "language": "en", "pause_after_ms": 900}, {"text": "Lapsena elasin ma maal.", "language": "et", "pause_after_ms": 2400}, {"text": "As a child I lived in the countryside. <<lapsena>> describes a period of life, the role of being a child.", "language": "en", "pause_after_ms": 900}, {"text": "The third is the abessive, with the ending <<ta>>. It means without, a bit like the English ending less in sugarless.", "language": "en", "pause_after_ms": 900}, {"text": "Ma joon kohvi suhkruta.", "language": "et", "pause_after_ms": 2400}, {"text": "I drink coffee without sugar. The word <<suhkur>> has the stem <<suhkru>>, so it becomes <<suhkruta>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma läksin kooli söömata.", "language": "et", "pause_after_ms": 2400}, {"text": "I went to school without eating. With verbs, the ending <<mata>> means without doing something.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is mixing the essive with the translative. <<töötab arstina>> means works as a doctor, but <<sai arstiks>> means became a doctor.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. I want coffee without milk. How would you say that in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Ma tahan piimata kohvi.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. <<piim>> becomes <<piima>>, then takes the ending <<ta>>, so <<piimata>> means without milk.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: <<ni>> means until, <<na>> means as, and <<ta>> means without. All three attach to the genitive stem.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson. Goodbye.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Advanced Consonant Gradation</b>

At A2 you met simple shortening: <code>lipp → lipu</code>. At B1 two harder patterns appear: consonants that vanish or change, and reverse gradation, where the dictionary form is the weak one.

🔻 Consonant vanishes or changes (strong → weak):
<code>tuba → toa</code>, <code>jõgi → jõe</code>, <code>rida → rea</code>
<code>sõda → sõja</code>, <code>lind → linnu</code>
Verbs too: <code>lugema → loen</code>, <code>tegema → teen</code>
🔺 Reverse gradation (weak → strong):
<code>mõte → mõtte</code>, <code>ratas → ratta</code>, <code>hammas → hamba</code>

💬 <i>Me istume väikeses toas.</i> — We are sitting in a small room.
💬 <i>Maja on jõe ääres.</i> — The house is by the river.
💬 <i>Ma kuulen linnu laulu.</i> — I hear the bird's song.
💬 <i>Ma ei saanud tema mõttest aru.</i> — I didn't understand his idea.
💬 <i>Ma loen igal õhtul raamatut.</i> — I read a book every evening.

⚠️ Do not find the dictionary form by just cutting the ending: <i>toas</i> comes from <i>tuba</i>, and <i>mõttes</i> from <i>mõte</i>, not "toa" or "mõtte".

💡 English has a few stem changes too (foot → feet, mouse → mice), but in Estonian they are everywhere, and a consonant can disappear completely. Always learn nouns as a pair: <code>tuba, toa</code>.$c$ WHERE id = 'b1-consonant-gradation-advanced';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-consonant-gradation-advanced', 'en', $s$[{"text": "Hello. Today we look at advanced consonant gradation. It helps you find the dictionary form of a word you meet in a text.", "language": "en", "pause_after_ms": 1000}, {"text": "At the previous level you saw that <<lipp>> becomes <<lipu>>. Now we look at two harder patterns.", "language": "en", "pause_after_ms": 1000}, {"text": "In the first pattern, a consonant disappears completely or turns into another sound. <<tuba>>, a room, becomes <<toa>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Me istume väikeses toas.", "language": "et", "pause_after_ms": 2400}, {"text": "We are sitting in a small room. In <<toas>> the sound <<b>> has gone, and the <<u>> has become <<o>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Maja on jõe ääres.", "language": "et", "pause_after_ms": 2400}, {"text": "The house is by the river. The dictionary says <<jõgi>>, but here the <<g>> has dropped out.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma kuulen linnu laulu.", "language": "et", "pause_after_ms": 2400}, {"text": "I hear the bird's song. <<lind>> becomes <<linnu>>, so the <<d>> has turned into an <<n>>.", "language": "en", "pause_after_ms": 1000}, {"text": "The second pattern is reverse gradation. Here the dictionary form is the weak one, and the other forms get stronger: <<mõte>> becomes <<mõtte>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ei saanud tema mõttest aru.", "language": "et", "pause_after_ms": 2400}, {"text": "I didn't understand his idea. <<mõttest>> has a double <<t>>, but the dictionary has <<mõte>> with a single <<t>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Other words follow the same pattern. <<ratas>> becomes <<ratta>>, and <<hammas>> becomes <<hamba>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Verbs show the first pattern as well, where a consonant disappears. <<lugema>> gives <<loen>>, and <<tegema>> gives <<teen>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma loen igal õhtul raamatut.", "language": "et", "pause_after_ms": 2400}, {"text": "I read a book every evening. In <<loen>> the <<g>> has gone, and the <<u>> has become <<o>>.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is to cut off the ending and take what is left as the dictionary form. There is no word <<toa>> in the dictionary. The right form is <<tuba>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. How do you say, I'm swimming in the river? A hint: the word is <<jõgi>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma ujun jões.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. <<jõgi>> became <<jões>>, and the <<g>> disappeared.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, always learn nouns as a pair, the basic form together with the genitive: <<tuba toa>>, <<mõte mõtte>>.", "language": "en", "pause_after_ms": 1000}, {"text": "English has a few changes like foot and feet, but Estonian does this all the time. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Conditional Mood (tingiv kõneviis) — "would"</b>

The conditional expresses what would happen: polite requests, wishes and unreal "if" situations.

🔧 Present stem + <code>-ks</code> + personal ending:
<code>söön → sööksin</code>, <code>tulen → tuleksin</code>, <code>loen → loeksin</code>
Endings: <code>-ksin, -ksid, -ks, -ksime, -ksite, -ksid</code>
Negative: <code>ei sööks</code> (the same for every person)
Past: <code>oleksin teinud</code> — I would have done

💬 <i>Ma tahaksin tassi kohvi.</i> — I would like a cup of coffee.
💬 <i>Kas sa aitaksid mind?</i> — Would you help me?
💬 <i>Kui mul oleks aega, läheksin kinno.</i> — If I had time, I would go to the cinema.
💬 <i>Ma ei ostaks seda autot.</i> — I wouldn't buy this car.
💬 <i>Me oleksime tulnud, aga sadas vihma.</i> — We would have come, but it was raining.

⚠️ English uses the past in the "if" half and "would" in the other: "If I had time, I would go". Estonian uses <code>-ks</code> in both clauses: <i>Kui mul oleks aega, läheksin.</i> For an unreal situation do not say <i>Kui mul on aega, läheksin.</i>

💡 Think of <code>-ks</code> as "would": <i>tahaksin</i> = I would like, the most useful polite word in any café.$c$ WHERE id = 'b1-conditional';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-conditional', 'en', $s$[{"text": "Hello. Today we learn the conditional mood in Estonian, called <<tingiv kõneviis>>. It is essential for polite requests and imagined situations.", "language": "en", "pause_after_ms": 1000}, {"text": "The rule is simple. Take the present stem of the verb, add <<ks>>, then the personal ending. <<söön>> becomes <<sööksin>>, I would eat.", "language": "en", "pause_after_ms": 1000}, {"text": "The personal endings are <<ksin>>, <<ksid>>, <<ks>>, <<ksime>>, <<ksite>>, and again <<ksid>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma tahaksin tassi kohvi.", "language": "et", "pause_after_ms": 2400}, {"text": "I would like a cup of coffee. <<tahaksin>> is the most polite way to ask for something in a café or a shop.", "language": "en", "pause_after_ms": 1000}, {"text": "Kas sa aitaksid mind?", "language": "et", "pause_after_ms": 2400}, {"text": "Would you help me? The ending <<ksid>> was added to the stem <<aita>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Kui mul oleks aega, läheksin kinno.", "language": "et", "pause_after_ms": 2600}, {"text": "If I had time, I would go to the cinema. Notice that both halves have <<ks>>: <<oleks>> and <<läheksin>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ei ostaks seda autot.", "language": "et", "pause_after_ms": 2400}, {"text": "I wouldn't buy this car. In the negative, the personal ending drops after <<ei>>, so it is <<ei ostaks>> for every person.", "language": "en", "pause_after_ms": 1000}, {"text": "Me oleksime tulnud, aga sadas vihma.", "language": "et", "pause_after_ms": 2600}, {"text": "We would have come, but it was raining. For the past, use <<oleksin>> plus the <<nud>> form, meaning I would have done.", "language": "en", "pause_after_ms": 1000}, {"text": "English builds the two halves differently: if I had, then I would go. Estonian simply uses <<ks>> on both sides.", "language": "en", "pause_after_ms": 1000}, {"text": "So for an imagined situation, don't say <<kui mul on aega>>. Say <<kui mul oleks aega>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. How do you say: If I had money, I would buy a new phone?", "language": "en", "pause_after_ms": 3800}, {"text": "Kui mul oleks raha, ostaksin uue telefoni.", "language": "et", "pause_after_ms": 2600}, {"text": "Yes, that's right. <<oleks>> and <<ostaksin>> are both in the conditional.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: present stem, then <<ks>>, then the personal ending. Use it for polite requests and imagined situations.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Relative Clauses: kes, mis, kus</b>

A relative clause describes a noun. In Estonian it follows the noun, set off by commas.

<code>kes</code> → people, <code>mis</code> → things, <code>kus</code> → places
The pronoun takes the case of its role inside the clause:
<code>kes → keda, kelle, kellega</code>
<code>mis → mida, mille, millest</code>

💬 <i>Mees, kes seal istub, on minu isa.</i> — The man who is sitting there is my father.
💬 <i>Naine, keda sa nägid, on minu õde.</i> — The woman you saw is my sister.
💬 <i>Sõber, kellega ma reisisin, elab Tartus.</i> — The friend I travelled with lives in Tartu.
💬 <i>Raamat, mille ma eile ostsin, on põnev.</i> — The book I bought yesterday is exciting.
💬 <i>Linn, kus ma elan, on väga ilus.</i> — The city where I live is very beautiful.

⚠️ English can drop the pronoun ("the woman you saw"), but Estonian never can: you always need <i>keda</i>, <i>mille</i> and so on. Mark the clause with commas: comma, clause, and a closing comma if the sentence continues.

💡 As an object, mis follows the normal object rule: whole, completed action → mille; ongoing action or negation → mida.$c$ WHERE id = 'b1-relative-clauses';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-relative-clauses', 'en', $s$[{"text": "Hello. Today we learn relative clauses. With them you can describe people and things, like the man sitting there, or the book I bought yesterday.", "language": "en", "pause_after_ms": 1000}, {"text": "Just like in English, the clause comes after the noun. But in Estonian it is always set off with commas.", "language": "en", "pause_after_ms": 1000}, {"text": "Use <<kes>> for people, <<mis>> for things, and <<kus>> for places.", "language": "en", "pause_after_ms": 1000}, {"text": "Mees, kes seal istub, on minu isa.", "language": "et", "pause_after_ms": 2400}, {"text": "The man who is sitting there is my father. <<kes>> is the subject of the clause, so it stays in the basic form.", "language": "en", "pause_after_ms": 900}, {"text": "Linn, kus ma elan, on väga ilus.", "language": "et", "pause_after_ms": 2400}, {"text": "The city where I live is very beautiful. To describe a place, use <<kus>>.", "language": "en", "pause_after_ms": 900}, {"text": "Now the most important rule. The pronoun takes the case that matches its role inside the clause.", "language": "en", "pause_after_ms": 1000}, {"text": "Naine, keda sa nägid, on minu õde.", "language": "et", "pause_after_ms": 2400}, {"text": "The woman you saw is my sister. She is the one you saw, so she is the object. That's why it is <<keda>>.", "language": "en", "pause_after_ms": 900}, {"text": "Sõber, kellega ma reisisin, elab Tartus.", "language": "et", "pause_after_ms": 2400}, {"text": "The friend I travelled with lives in Tartu. <<kellega>> means with whom. English can put with at the end, but Estonian puts the ending on the pronoun.", "language": "en", "pause_after_ms": 900}, {"text": "Raamat, mida ma loen, on huvitav.", "language": "et", "pause_after_ms": 2400}, {"text": "The book I am reading is interesting. The reading is still going on, so we use the partitive <<mida>>.", "language": "en", "pause_after_ms": 900}, {"text": "Raamat, mille ma eile ostsin, on põnev.", "language": "et", "pause_after_ms": 2400}, {"text": "The book I bought yesterday is exciting. The buying is finished, so we use <<mille>>.", "language": "en", "pause_after_ms": 900}, {"text": "A common mistake is forgetting the comma after the clause. If the sentence goes on, use two commas. And unlike English, you can never leave out the pronoun.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. The woman who helped me yesterday is a doctor. How would you say that in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Naine, kes mind eile aitas, on arst.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. <<kes>> is the subject, so it stays in the basic form, and the verb <<aitama>> needs <<mind>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up, the relative clause follows the noun, and the pronoun takes the case of its role in the clause.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson. Goodbye.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Indirect Questions (kas-clauses)</b>

An indirect question is a question placed inside another sentence: "I don't know whether he is coming." It follows verbs like <code>teadma</code>, <code>küsima</code>, <code>mäletama</code>, <code>ütlema</code>.

🔧 Yes/no question → <code>kas</code> + normal clause:
<code>Kas ta homme tuleb? → Ma ei tea, kas ta homme tuleb.</code>
🔧 A question word stays at the start of the clause:
<code>Kus ta elab? → Ma tean, kus ta elab.</code>
Put a comma before the clause. The tense does not change.

💬 <i>Ma ei tea, kas ta homme tuleb.</i> — I don't know whether he is coming tomorrow.
💬 <i>Ma tean, kus ta elab.</i> — I know where he lives.
💬 <i>Kas sa tead, millal rong väljub?</i> — Do you know when the train leaves?
💬 <i>Ma ei mäleta, kuhu ma võtmed panin.</i> — I don't remember where I put the keys.
💬 <i>Ta küsis, kas ma räägin eesti keelt.</i> — She asked whether I speak Estonian.

⚠️ English often says "if" here ("I don't know if he's coming"), but Estonian <i>kui</i> is only for conditions. Use <i>kas</i> with a normal clause: <i>kas ta tuleb</i>. Never drop <i>kas</i>.

💡 English changes the word order ("where does he live" → "where he lives"); Estonian doesn't. Take the direct question as it is, put a main clause and a comma in front, and drop the question mark.$c$ WHERE id = 'b1-indirect-questions';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-indirect-questions', 'en', $s$[{"text": "Hello. Today we look at indirect questions, where a question sits inside another sentence. You'll use them all the time in everyday speech.", "language": "en", "pause_after_ms": 1000}, {"text": "Yes or no questions start with <<kas>>. In an indirect question <<kas>> stays put, and you add a main clause and a comma in front.", "language": "en", "pause_after_ms": 1000}, {"text": "Kas ta homme tuleb?", "language": "et", "pause_after_ms": 2400}, {"text": "Will he come tomorrow? This is a direct question.", "language": "en", "pause_after_ms": 900}, {"text": "Ma ei tea, kas ta homme tuleb.", "language": "et", "pause_after_ms": 2400}, {"text": "I don't know whether he is coming tomorrow. The question mark has gone, and the rest of the sentence is exactly the same.", "language": "en", "pause_after_ms": 1000}, {"text": "Question words also stay at the start of the clause, words like <<kus>>, <<mis>>, <<millal>> and <<kuhu>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma tean, kus ta elab.", "language": "et", "pause_after_ms": 2400}, {"text": "I know where he lives. <<kus>> starts the clause, and the verb <<elab>> stays in its usual place.", "language": "en", "pause_after_ms": 1000}, {"text": "Kas sa tead, millal rong väljub?", "language": "et", "pause_after_ms": 2400}, {"text": "Do you know when the train leaves? Here the main clause is itself a question, so there is a question mark at the end.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ei mäleta, kuhu ma võtmed panin.", "language": "et", "pause_after_ms": 2400}, {"text": "I don't remember where I put the keys. <<kuhu>> means where to.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta küsis, kas ma räägin eesti keelt.", "language": "et", "pause_after_ms": 2400}, {"text": "She asked whether I speak Estonian. The main verb is in the past, but <<räägin>> stays in the present, where English would usually say spoke.", "language": "en", "pause_after_ms": 1000}, {"text": "In English the word order changes: where does he live becomes where he lives. In Estonian the clause stays just as it was.", "language": "en", "pause_after_ms": 1000}, {"text": "And don't drop <<kas>>. English speakers want to use <<kui>> here, because English says if, but the right word is <<kas>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. How do you say: I don't know what time it is?", "language": "en", "pause_after_ms": 3800}, {"text": "Ma ei tea, mis kell on.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The direct question was <<mis kell on>>, and you just put <<ma ei tea>> in front.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: take the direct question as it is, and put a main clause and a comma in front. In yes or no questions, <<kas>> always stays.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Purpose Clauses (selleks et, et)</b>

Purpose clauses answer "why, for what?" Like English ("to find" vs "so that you understand"), Estonian chooses the form by the subject.

🔧 Same subject → <code>et</code> + da-infinitive: <code>et leida</code>
🔧 Different subject → <code>et</code> + conditional: <code>et sa aru saaksid</code>
🔧 <code>selleks et</code> stresses the purpose and can open the sentence
🔧 Negative: <code>et mitte</code> + da-infinitive: <code>et mitte hilineda</code>
🔧 After verbs of motion → ma-infinitive, no <code>et</code>: <code>läks ostma</code>

💬 <i>Ma õpin eesti keelt, et Eestis tööd leida.</i> — I'm learning Estonian to find work in Estonia.
💬 <i>Ma räägin aeglaselt, et sa aru saaksid.</i> — I speak slowly so that you understand.
💬 <i>Selleks et hästi magada, ära joo õhtul kohvi.</i> — To sleep well, don't drink coffee in the evening.
💬 <i>Ma tõusen vara, et mitte hilineda.</i> — I get up early so as not to be late.
💬 <i>Ta läks poodi leiba ostma.</i> — He went to the shop to buy bread.

⚠️ When the subject changes, an infinitive is wrong: not <i>et sa aru saada</i>, but <i>et sa aru saaksid</i>.

💡 Ask one question: "Is it the same person?" Yes → <code>et</code> + da. No → <code>et</code> + <code>-ks</code>.$c$ WHERE id = 'b1-purpose-clauses';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-purpose-clauses', 'en', $s$[{"text": "Hello. Today we learn purpose clauses, the Estonian way to say in order to, or so that. There are a few patterns, and the choice depends on the subject.", "language": "en", "pause_after_ms": 1000}, {"text": "If the subject is the same, use <<et>> followed by the <<da>> infinitive.", "language": "en", "pause_after_ms": 900}, {"text": "Ma õpin eesti keelt, et Eestis tööd leida.", "language": "et", "pause_after_ms": 2600}, {"text": "I'm learning Estonian to find work in Estonia. I learn and I find, so the infinitive <<leida>> is enough.", "language": "en", "pause_after_ms": 1000}, {"text": "If the subject changes, use <<et>> followed by the conditional, with the ending <<ks>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma räägin aeglaselt, et sa aru saaksid.", "language": "et", "pause_after_ms": 2400}, {"text": "I speak slowly so that you understand. I speak, but you understand, so <<saaksid>> is in the conditional.", "language": "en", "pause_after_ms": 1000}, {"text": "<<selleks et>> puts more stress on the purpose, and it can also start the sentence.", "language": "en", "pause_after_ms": 900}, {"text": "Selleks et hästi magada, ära joo õhtul kohvi.", "language": "et", "pause_after_ms": 2600}, {"text": "To sleep well, don't drink coffee in the evening. The purpose comes first, followed by a comma.", "language": "en", "pause_after_ms": 1000}, {"text": "For a negative purpose, use <<et mitte>> with the <<da>> infinitive.", "language": "en", "pause_after_ms": 900}, {"text": "Ma tõusen vara, et mitte hilineda.", "language": "et", "pause_after_ms": 2400}, {"text": "I get up early so as not to be late. Here <<mitte>> gives the negative meaning.", "language": "en", "pause_after_ms": 1000}, {"text": "After verbs of motion you don't need a conjunction at all. Just use the <<ma>> infinitive.", "language": "en", "pause_after_ms": 900}, {"text": "Ta läks poodi leiba ostma.", "language": "et", "pause_after_ms": 2400}, {"text": "He went to the shop to buy bread. <<läks>> is a verb of motion, so the form is <<ostma>>.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is using the infinitive when the subject changes. <<et sa aru saada>> is wrong, the right form is <<et sa aru saaksid>>. Think of English to versus so that.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. How do you say: I read every day to speak better?", "language": "en", "pause_after_ms": 3800}, {"text": "Ma loen iga päev, et paremini rääkida.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The one who reads and the one who speaks are the same person, so the infinitive <<rääkida>> is used.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: same subject, <<et>> plus the <<da>> infinitive. Different subject, <<et>> plus the conditional. After a verb of motion, the <<ma>> infinitive.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Passive Voice (umbisikuline tegumood)</b>

The Estonian passive is really impersonal: the doer is unknown or unimportant and is always a person. Use it for rules, habits, signs and news.

🔧 Present: <code>-takse / -dakse</code> — <code>räägitakse</code>, <code>lauldakse</code>
🔧 Past: <code>-ti / -di</code> — <code>ehitati</code>, <code>lauldi</code>
🔧 Negative: <code>ei räägita</code>, past <code>ei räägitud</code>
A whole object is in the nominative, not the genitive: <code>Ma avan poe → Pood avatakse.</code>

💬 <i>Siin räägitakse eesti keelt.</i> — Estonian is spoken here.
💬 <i>Eestis lauldakse palju.</i> — People sing a lot in Estonia.
💬 <i>Pood avatakse kell kaheksa.</i> — The shop opens at eight.
💬 <i>Maja ehitati eelmisel aastal.</i> — The house was built last year.
💬 <i>Siin ei suitsetata.</i> — No smoking here.

⚠️ In English you can add the doer with "by" ("built by my father"). In Estonian this sounds unnatural. If the doer matters, use an active sentence: <i>Isa ehitas maja.</i>

💡 English often translates it with "people" or "they": <i>räägitakse</i> = people say, <i>ehitati</i> = was built, they built.$c$ WHERE id = 'b1-passive';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-passive', 'en', $s$[{"text": "Hello. Today we learn the Estonian passive, called <<umbisikuline tegumood>>. You meet it every day in rules, on signs and in the news.", "language": "en", "pause_after_ms": 1000}, {"text": "In this form nobody says who does the action, and the doer is always people. In the present tense the verb takes <<takse>> or <<dakse>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Siin räägitakse eesti keelt.", "language": "et", "pause_after_ms": 2400}, {"text": "Estonian is spoken here. The verb <<rääkima>> became <<räägitakse>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Eestis lauldakse palju.", "language": "et", "pause_after_ms": 2400}, {"text": "People sing a lot in Estonia. For verbs like <<laulma>>, whose stem ends in <<l>>, the ending is <<dakse>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Pood avatakse kell kaheksa.", "language": "et", "pause_after_ms": 2400}, {"text": "The shop opens at eight. The active sentence would be <<ma avan poe>>, but in the passive the object stays in the basic form: <<pood>>.", "language": "en", "pause_after_ms": 1100}, {"text": "In the past tense the ending is <<ti>> or <<di>>.", "language": "en", "pause_after_ms": 800}, {"text": "Maja ehitati eelmisel aastal.", "language": "et", "pause_after_ms": 2400}, {"text": "The house was built last year. From the verb <<ehitama>> we get <<ehitati>>.", "language": "en", "pause_after_ms": 1000}, {"text": "In the negative, after <<ei>>, the present tense takes <<ta>> or <<da>>.", "language": "en", "pause_after_ms": 900}, {"text": "Siin ei suitsetata.", "language": "et", "pause_after_ms": 2400}, {"text": "No smoking here. You will see this sentence on signs very often.", "language": "en", "pause_after_ms": 1000}, {"text": "In English you can add the doer with the word by. In Estonian that isn't natural. If the doer matters, use an active sentence: <<isa ehitas maja>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. How do you say: People drink milk here? A hint: the verb is <<jooma>>.", "language": "en", "pause_after_ms": 3800}, {"text": "Siin juuakse piima.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The passive of <<jooma>> is irregular: <<juuakse>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: <<takse>> in the present, <<ti>> in the past, and <<ei>> with <<ta>> in the negative. The doer is never named.", "language": "en", "pause_after_ms": 1000}, {"text": "That's all for today. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Participle Constructions (-v, -tav)</b>

Present participles turn a verb into an adjective: "sleeping", "being built", "edible". They let you pack a whole clause in front of a noun.

🔧 Active <code>-v</code> (the one doing it): ma-stem + <code>v</code>, after a consonant <code>-ev</code>
<code>magama → magav</code>, <code>lugema → lugev</code>, <code>jooksma → jooksev</code>
🔧 Passive <code>-tav / -dav</code> (being done or can be done): passive <code>-kse</code> → <code>-v</code>
<code>loetakse → loetav</code>, <code>ehitatakse → ehitatav</code>, irregular <code>söödav</code>
They decline like adjectives: <code>magav laps → magavat last</code>

💬 <i>Raamatut lugev tüdruk istub pargis.</i> — The girl reading a book is sitting in the park.
💬 <i>Ma nägin magavat last.</i> — I saw a sleeping child.
💬 <i>Ehitatav maja asub kesklinnas.</i> — The house being built is in the city centre.
💬 <i>Kas see seen on söödav?</i> — Is this mushroom edible?
💬 <i>Tuleval nädalal on eksam.</i> — There is an exam next week.

⚠️ Do not mix the two: <i>lugev raamat</i> would be "a book that reads". A book that is read or readable is <i>loetav raamat</i>.

💡 Unlike English, the whole phrase goes before the noun: <i>raamatut lugev tüdruk</i> = literally "a book-reading girl". The past forms -nud and -tud come at B2.$c$ WHERE id = 'b1-participle-constructions';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-participle-constructions', 'en', $s$[{"text": "Hello. Today we learn present participles. They turn a verb into an adjective, so a whole clause fits into one short phrase.", "language": "en", "pause_after_ms": 1000}, {"text": "The active form describes the one doing the action and ends in <<v>>. From <<magama>> we get <<magav>>, sleeping.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma nägin magavat last.", "language": "et", "pause_after_ms": 2400}, {"text": "I saw a sleeping child. <<magav>> declines like an adjective and becomes <<magavat>>, because the object is in the partitive.", "language": "en", "pause_after_ms": 1000}, {"text": "After a consonant stem the ending is <<ev>>. From <<jooksma>> we get <<jooksev>>, running or flowing.", "language": "en", "pause_after_ms": 1000}, {"text": "Raamatut lugev tüdruk istub pargis.", "language": "et", "pause_after_ms": 2400}, {"text": "The girl reading a book is sitting in the park. Unlike English, the whole phrase goes before the noun, like a book reading girl.", "language": "en", "pause_after_ms": 1000}, {"text": "The passive form describes what is being done and ends in <<tav>> or <<dav>>. From the passive <<loetakse>> we get <<loetav>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ehitatav maja asub kesklinnas.", "language": "et", "pause_after_ms": 2400}, {"text": "The house being built is in the city centre. <<ehitatav>> means being built.", "language": "en", "pause_after_ms": 1000}, {"text": "Kas see seen on söödav?", "language": "et", "pause_after_ms": 2400}, {"text": "Is this mushroom edible? The passive form often means can be done, like the English ending able. <<söödav>> is irregular.", "language": "en", "pause_after_ms": 1000}, {"text": "Tuleval nädalal on eksam.", "language": "et", "pause_after_ms": 2400}, {"text": "There is an exam next week. <<tulev>> means coming, and here it is declined as <<tuleval>>.", "language": "en", "pause_after_ms": 1000}, {"text": "The most common mistake is mixing the two. <<lugev raamat>> would be a book that reads. A book that is read is <<loetav raamat>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. How do you say: Running water is cold?", "language": "en", "pause_after_ms": 3800}, {"text": "Jooksev vesi on külm.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. <<jooksev>> is the active form, and like an adjective it stands before the noun.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: <<v>> for the one doing it, <<tav>> for what is being done. Both decline like adjectives and go before the noun.", "language": "en", "pause_after_ms": 1000}, {"text": "We'll meet the past participles at the next level. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Reported Speech with et</b>

To report what someone said or thinks, Estonian uses a reporting verb, a comma, <code>et</code> ("that") and a normal clause.

<code>ütlema, rääkima, arvama, kirjutama + , et …</code>
Direct: <i>Mari: "Ma olen väsinud."</i>
Reported: <i>Mari ütles, et ta on väsinud.</i>
Change the person (<code>ma → ta</code>), but keep the tense as it was spoken. No backshift!

💬 <i>Mari ütles, et ta on väsinud.</i> — Mari said she was tired.
💬 <i>Peeter ütles, et ta tuleb homme.</i> — Peeter said he would come tomorrow.
💬 <i>Ta kirjutas, et ta elab nüüd Tartus.</i> — She wrote that she now lives in Tartu.
💬 <i>Sa ütlesid, et sul on aega.</i> — You said you had time.
💬 <i>Ema palus, et ma helistaksin talle.</i> — Mum asked me to call her. (a request → conditional)

⚠️ English shifts the tense back ("she said she was tired"); Estonian keeps the original tense. After et comes a full clause with a finite verb, the comma before et is obligatory, and et is not left out the way "that" can be.

💡 In the news you will also meet the -vat form (Ta olevat haige — he is said to be ill), covered in the quotative mood lesson.$c$ WHERE id = 'b1-reported-speech';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b1-reported-speech', 'en', $s$[{"text": "Hello. Today we learn how to report what other people say. It's one of the structures you'll need most in everyday conversation.", "language": "en", "pause_after_ms": 1000}, {"text": "The rule is simple. After a verb like say or think, put a comma and the word <<et>>, meaning that, followed by a normal clause.", "language": "en", "pause_after_ms": 1000}, {"text": "First, direct speech. Mari says this.", "language": "en", "pause_after_ms": 700}, {"text": "Ma olen väsinud.", "language": "et", "pause_after_ms": 2200}, {"text": "That means, I am tired. Now let's report it.", "language": "en", "pause_after_ms": 800}, {"text": "Mari ütles, et ta on väsinud.", "language": "et", "pause_after_ms": 2400}, {"text": "Mari said she was tired. <<ma>> has become <<ta>>, but the verb has stayed the same.", "language": "en", "pause_after_ms": 1000}, {"text": "Peeter ütles, et ta tuleb homme.", "language": "et", "pause_after_ms": 2400}, {"text": "Peeter said he would come tomorrow. The main verb is in the past, but <<tuleb>> stays as it was spoken.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta kirjutas, et ta elab nüüd Tartus.", "language": "et", "pause_after_ms": 2400}, {"text": "She wrote that she now lives in Tartu. Estonian doesn't shift the tense back the way English does. The words keep their original tense.", "language": "en", "pause_after_ms": 1000}, {"text": "Sa ütlesid, et sul on aega.", "language": "et", "pause_after_ms": 2400}, {"text": "You said you had time. You were the speaker, so <<mul>> became <<sul>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ema palus, et ma helistaksin talle.", "language": "et", "pause_after_ms": 2400}, {"text": "Mum asked me to call her. When you report a request, the verb goes into the conditional, as in <<helistaksin>>.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake for English speakers is shifting the tense back. In Estonian it stays as spoken, and after <<et>> there is always a full clause.", "language": "en", "pause_after_ms": 900}, {"text": "Don't forget the comma either. A comma before <<et>> is always required, and unlike English that, <<et>> is not left out.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Jaan says he is hungry. How would you report that in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Jaan ütleb, et ta on näljane.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. <<ütleb>> is the reporting verb, and <<ta on näljane>> is a full clause with a finite verb.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: a reporting verb, a comma, <<et>>, and a normal clause. Change the person, keep the tense.", "language": "en", "pause_after_ms": 1000}, {"text": "See you in the next lesson. Goodbye.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();

--changeset english-grammar-content:b2 splitStatements:false
UPDATE grammar_lessons SET content = $c$<b>Imperative Mood in Full (käskiv kõneviis)</b>
The imperative gives commands, requests, instructions and advice. At this level you use all its persons, not only "you".

<code>sa</code>: present stem → <code>tulen → tule</code>, <code>vaatan → vaata</code>; irregular <code>mine</code>
<code>te</code> (also polite): drop <code>-da/-ta/-a</code> from the da-infinitive and add <code>-ge</code> (<code>-ke</code> after a -ta infinitive or h): <code>tulla → tulge</code>, <code>vaadata → vaadake</code>, <code>teha → tehke</code>
<b>let's</b> (formal): <code>-gem/-kem</code>: <code>olgem</code>; in speech: <code>Lähme!</code>
<b>he/she/they</b>: <code>-gu/-ku</code>: <code>tulgu</code>, <code>tehku</code>
Negative: <code>ära tule</code>, <code>ärge tulge</code>, <code>ärgu tulgu</code>

💬 <i>Vaadake seda pilti.</i> — Look at this picture.
💬 <i>Ära unusta võtmeid!</i> — Don't forget the keys!
💬 <i>Ärge muretsege, kõik on korras.</i> — Don't worry, everything is fine.
💬 <i>Olgem ausad.</i> — Let's be honest.
💬 <i>Tehku ta, mis tahab.</i> — Let him do what he wants.

⚠️ English "don't come" is the same for one person or several. The Estonian negative has two words, and both must agree: <i>ärge tulge</i>, never <i>ära tulge</i> or <i>ärge tule</i>.

💡 The negative word copies the verb: <code>ära</code> + sa-form, <code>ärge</code> + te-form, <code>ärgu</code> + gu-form.$c$ WHERE id = 'b2-imperative';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-imperative', 'en', $s$[{"text": "Hello. In this lesson we cover the imperative mood, <<käskiv kõneviis>>, in all its persons.", "language": "en", "pause_after_ms": 900}, {"text": "For one person you know well, the present stem is enough. <<tulen>> gives <<tule>>, and <<vaatan>> gives <<vaata>>.", "language": "en", "pause_after_ms": 1000}, {"text": "For several people, drop the end of the <<da>> infinitive and add <<ge>> or <<ke>>. <<tulla>> becomes <<tulge>>, and <<vaadata>> becomes <<vaadake>>.", "language": "en", "pause_after_ms": 1100}, {"text": "Vaadake seda pilti.", "language": "et", "pause_after_ms": 2300}, {"text": "Look at this picture. This form is also the polite way to speak to one person.", "language": "en", "pause_after_ms": 1000}, {"text": "Pange palun aken kinni.", "language": "et", "pause_after_ms": 2300}, {"text": "Please close the window. In the imperative a total object stays in the nominative, so <<aken>> does not change.", "language": "en", "pause_after_ms": 1000}, {"text": "A negative command has two words, and both agree. Use <<ära>> for one person and <<ärge>> for several.", "language": "en", "pause_after_ms": 1000}, {"text": "Ära unusta võtmeid!", "language": "et", "pause_after_ms": 2300}, {"text": "Don't forget the keys! In a negative sentence the object is partitive, so we say <<võtmeid>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ärge muretsege, kõik on korras.", "language": "et", "pause_after_ms": 2300}, {"text": "Don't worry, everything is fine. Both words are in the plural form.", "language": "en", "pause_after_ms": 1000}, {"text": "There are two more forms. The ending <<gem>> means let's, and the ending <<gu>> gives an order about him, her or them.", "language": "en", "pause_after_ms": 1000}, {"text": "Olgem ausad.", "language": "et", "pause_after_ms": 2300}, {"text": "Let's be honest. This form is formal. In everyday speech you will hear forms like <<lähme>> much more often.", "language": "en", "pause_after_ms": 1000}, {"text": "Tehku ta, mis tahab.", "language": "et", "pause_after_ms": 2300}, {"text": "Let him do what he wants. The ending <<gu>> works like English let him or let her, but it is a single verb form.", "language": "en", "pause_after_ms": 1000}, {"text": "Here is a common mistake. English don't come is the same for one person or many. In Estonian <<ära tulge>> is wrong. The correct form is <<ärge tulge>>.", "language": "en", "pause_after_ms": 1100}, {"text": "Now you try. You want to politely ask several people to sit down. How do you say it in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Istuge, palun.", "language": "et", "pause_after_ms": 2300}, {"text": "Correct. From the infinitive <<istuda>> we get <<istuge>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: the stem for one person, <<ge>> or <<ke>> for several, and <<ära>> or <<ärge>> in the negative.", "language": "en", "pause_after_ms": 1000}, {"text": "This week, try making your everyday requests in the imperative. See you next time.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Object Case Rules — Complete Guide (sihitis)</b>
Estonian has a partial object (partitive) and a total object. The choice depends on whether the action is complete and affects the whole object, not on "the" versus "a".

<b>Partitive object:</b> negation, ongoing action, part of an amount, or verbs of feeling that always take it (<code>armastama, kartma, vihkama, tänama</code>).
<b>Total object, singular:</b> genitive <code>raamatu</code>, but nominative <code>raamat</code> after an imperative or in an impersonal sentence.
<b>Total object, plural:</b> always nominative <code>raamatud</code>.

💬 <i>Ma lugesin raamatu läbi.</i> — I read the book to the end.
💬 <i>Ma loen raamatut.</i> — I am reading the book.
💬 <i>Ma ei ostnud autot.</i> — I did not buy the car.
💬 <i>Too raamat siia!</i> — Bring the book here!
💬 <i>Maja ehitati valmis.</i> — The house was finished.
💬 <i>Ma ostsin uued raamatud.</i> — I bought the new books.

⚠️ Do not link the genitive object to English "the". "I am reading the book" is definite, yet Estonian says <i>Ma loen raamatut</i>, because the reading is not finished.

💡 Particles such as <code>läbi, ära, valmis, kinni</code> usually mark a finished action, so in affirmative sentences they normally come with a total object: <i>Ma sõin koogi ära.</i>$c$ WHERE id = 'b2-object-rules';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-object-rules', 'en', $s$[{"text": "Hello. In this lesson we go through all the rules for the case of the object. The right case changes the meaning of the sentence.", "language": "en", "pause_after_ms": 900}, {"text": "Estonian has two kinds of object. The partial object is in the partitive. The total object is usually in the genitive in the singular.", "language": "en", "pause_after_ms": 1000}, {"text": "The choice is not about the versus a. The real question is: is the action finished, and did it affect the whole object?", "language": "en", "pause_after_ms": 1000}, {"text": "Ma lugesin raamatu läbi.", "language": "et", "pause_after_ms": 2400}, {"text": "I read the book to the end. The action is finished, so <<raamatu>>. The word <<läbi>> also stresses that it is complete.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma loen raamatut.", "language": "et", "pause_after_ms": 2400}, {"text": "I am reading the book. The action is still going on, so we use the partitive <<raamatut>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ei ostnud autot.", "language": "et", "pause_after_ms": 2400}, {"text": "I did not buy the car. In a negative sentence the object is always partitive.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma armastan seda linna.", "language": "et", "pause_after_ms": 2400}, {"text": "I love this city. Verbs of feeling like <<armastama>> always take the partitive.", "language": "en", "pause_after_ms": 1000}, {"text": "Sometimes the total object stays in the nominative. You see this in the imperative, in impersonal sentences and in the plural.", "language": "en", "pause_after_ms": 1000}, {"text": "Too raamat siia!", "language": "et", "pause_after_ms": 2400}, {"text": "Bring the book here! In the imperative the total object stays in the nominative, so <<raamat>> does not change.", "language": "en", "pause_after_ms": 1000}, {"text": "Maja ehitati valmis.", "language": "et", "pause_after_ms": 2400}, {"text": "The house was finished. In an impersonal sentence the total object stays in the nominative, so <<maja>> does not change.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma ostsin uued raamatud.", "language": "et", "pause_after_ms": 2400}, {"text": "I bought the new books. A plural total object is always nominative, like <<raamatud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Here is a common mistake. Do not link the genitive object to English the. Even for I am reading the book, Estonian uses the partitive.", "language": "en", "pause_after_ms": 1100}, {"text": "Now you try. Say: I ate the whole cake, there is none left. How do you say it in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Ma sõin koogi ära.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The whole cake was eaten, so we use the genitive <<koogi>>, together with <<ära>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: negation and ongoing actions take the partitive. A finished action that affects the whole object takes the total object.", "language": "en", "pause_after_ms": 1000}, {"text": "With every new sentence, ask yourself: is the action finished? See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Pluperfect (enneminevik) — "had done"</b>

The pluperfect describes an action that was already finished before another moment in the past. It is the perfect tense moved one step further back.

<code>olin / olid / oli / olime / olite / olid + söönud</code>
Negative: <code>ei olnud + söönud</code> (same for all persons)
Passive: <code>oli + -tud</code> → <code>oli kaetud</code>

💬 <i>Kui ma jaama jõudsin, oli rong juba läinud.</i> — When I got to the station, the train had already left.
💬 <i>Me olime enne reisi palju eesti keelt õppinud.</i> — We had studied a lot of Estonian before the trip.
💬 <i>Ma ei olnud seda filmi varem näinud.</i> — I had not seen this film before.
💬 <i>Kui külalised saabusid, oli laud juba kaetud.</i> — When the guests arrived, the table had already been set.

⚠️ The negative auxiliary never changes: <i>ma ei olnud näinud</i>, not <i>ma ei olin näinud</i>. Also compare <i>Kui ma tulin, lahkus ta</i> (he left as I arrived) with <i>Kui ma tulin, oli ta juba lahkunud</i> (he had left before I arrived).

💡 English turns "have eaten" into "had eaten"; Estonian does the same by putting <code>olema</code> into the past: <i>olen söönud</i> (I have eaten) → <i>olin söönud</i> (I had eaten).$c$ WHERE id = 'b2-pluperfect';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-pluperfect', 'en', $s$[{"text": "In this lesson we look at the past before the past, the <<enneminevik>>. It shows which event in a story happened first.", "language": "en", "pause_after_ms": 1000}, {"text": "The rule is simple. Put <<olema>> into the past tense and add the <<nud>> participle. It matches English had done.", "language": "en", "pause_after_ms": 1000}, {"text": "The helper verb changes for person: <<olin>>, <<olid>>, <<oli>>, <<olime>>, <<olite>>, <<olid>>. The participle never changes.", "language": "en", "pause_after_ms": 1000}, {"text": "Kui ma jaama jõudsin, oli rong juba läinud.", "language": "et", "pause_after_ms": 2400}, {"text": "When I got to the station, the train had already left. The train left before I arrived, so we use <<oli läinud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Me olime enne reisi palju eesti keelt õppinud.", "language": "et", "pause_after_ms": 2400}, {"text": "We had studied a lot of Estonian before the trip. For we, the helper verb is <<olime>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta oli võtmed koju unustanud.", "language": "et", "pause_after_ms": 2200}, {"text": "He had left his keys at home. The participle usually goes to the end of the sentence.", "language": "en", "pause_after_ms": 1000}, {"text": "Kui külalised saabusid, oli laud juba kaetud.", "language": "et", "pause_after_ms": 2400}, {"text": "When the guests arrived, the table had already been set. In the passive we use the <<tud>> participle: <<oli kaetud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "In the negative we use <<ei olnud>> for every person, followed again by the <<nud>> participle.", "language": "en", "pause_after_ms": 800}, {"text": "Ma ei olnud seda filmi varem näinud.", "language": "et", "pause_after_ms": 2400}, {"text": "I had not seen this film before. Careful: you cannot say <<ma ei olin>>. The correct form is <<ma ei olnud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now let's compare two sentences.", "language": "en", "pause_after_ms": 800}, {"text": "Kui ma tulin, lahkus ta.", "language": "et", "pause_after_ms": 2400}, {"text": "When I came, he left. The two events happened at almost the same time.", "language": "en", "pause_after_ms": 900}, {"text": "Kui ma tulin, oli ta juba lahkunud.", "language": "et", "pause_after_ms": 2400}, {"text": "When I came, he had already left. His leaving happened before my arrival.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. Translate into Estonian: When we got to the cinema, the film had already started.", "language": "en", "pause_after_ms": 3800}, {"text": "Kui me kinno jõudsime, oli film juba alanud.", "language": "et", "pause_after_ms": 2400}, {"text": "The participle of <<algama>> is <<alanud>>, and the helper verb is <<oli>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: for something that happened before another past event, use <<olin>>, <<olid>> or <<oli>> with the <<nud>> participle.", "language": "en", "pause_after_ms": 1000}, {"text": "Try this structure in the next story you tell. See you soon.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Past Participles -nud and -tud (kesksõnad)</b>
Both past participles do double duty: they build the perfect tenses and they work as adjectives. <code>-nud</code> describes the doer (active), <code>-tud</code> what was done to something (passive).

<code>-nud</code> from the da-infinitive stem: <code>lugeda → lugenud</code>, <code>elada → elanud</code>; irregular: <code>teha → teinud</code>, <code>minna → läinud</code>
<code>-tud/-dud</code> from the passive stem: <code>tehakse → tehtud</code>, <code>loetakse → loetud</code>, <code>kirjutatakse → kirjutatud</code>
Before a noun they never change for case or number: <code>väsinud lastega</code>, <code>suletud uste taga</code>

💬 <i>Väsinud õpetaja istus toolile.</i> — The tired teacher sat down on the chair.
💬 <i>See on hästi kirjutatud raamat.</i> — This is a well-written book.
💬 <i>Ma rääkisin väsinud lastega.</i> — I talked to the tired children.
💬 <i>Kas sa oled seda filmi näinud?</i> — Have you seen this film?
💬 <i>Töö on juba tehtud.</i> — The work is already done.

⚠️ English uses "written" both in "has written" and in "a written book". Estonian keeps them apart: <code>-nud</code> = has written, <code>-tud</code> = written. So not <i>kirjutanud raamat</i> (a book that has written something), but <i>kirjutatud raamat</i>.

💡 Ask yourself: did the noun do it, or was it done to the noun?$c$ WHERE id = 'b2-nud-tud-participles';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-nud-tud-participles', 'en', $s$[{"text": "Hello. Today we look at the participles <<nud>> and <<tud>>. You meet them both in tenses and as adjectives.", "language": "en", "pause_after_ms": 900}, {"text": "The rule is simple. <<nud>> describes the doer, so it is active. <<tud>> describes the thing the action was done to, so it is passive.", "language": "en", "pause_after_ms": 1000}, {"text": "The <<nud>> form is built from the <<da>> infinitive. <<lugeda>> becomes <<lugenud>>, and <<elada>> becomes <<elanud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "The <<tud>> form comes from the passive stem. <<tehakse>> gives <<tehtud>>, and <<loetakse>> gives <<loetud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Väsinud õpetaja istus toolile.", "language": "et", "pause_after_ms": 2400}, {"text": "The tired teacher sat down on the chair. The teacher got tired herself, so <<väsinud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "See on hästi kirjutatud raamat.", "language": "et", "pause_after_ms": 2400}, {"text": "This is a well written book. Someone wrote the book, so <<kirjutatud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Kadunud võtmed leiti üles.", "language": "et", "pause_after_ms": 2400}, {"text": "The lost keys were found. The keys got lost on their own, so we use the active <<kadunud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma rääkisin väsinud lastega.", "language": "et", "pause_after_ms": 2400}, {"text": "I talked to the tired children. The noun became <<lastega>>, but <<väsinud>> did not change at all.", "language": "en", "pause_after_ms": 1000}, {"text": "With the verb <<olema>>, these forms also build the perfect tenses.", "language": "en", "pause_after_ms": 1000}, {"text": "Kas sa oled seda filmi näinud?", "language": "et", "pause_after_ms": 2400}, {"text": "Have you seen this film? <<oled näinud>> asks about an experience.", "language": "en", "pause_after_ms": 1000}, {"text": "Töö on juba tehtud.", "language": "et", "pause_after_ms": 2400}, {"text": "The work is already done. The work is what was done, so we use the passive <<tehtud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "English uses written both for has written and for a written book. Estonian keeps them apart. A written book is <<kirjutatud raamat>>, not <<kirjutanud raamat>>.", "language": "en", "pause_after_ms": 1100}, {"text": "Now you try. Say: The letter has already been written. How do you say it in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Kiri on juba kirjutatud.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. The letter is the thing that was written, so we chose the passive <<kirjutatud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: <<nud>> for the doer, <<tud>> for what was done. Before a noun they never change.", "language": "en", "pause_after_ms": 1000}, {"text": "Ask yourself: did the noun do it, or was it done to the noun? See you soon.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Comitative Case in Depth (kaasaütlev)</b>
You know that <code>-ga</code> means "with". At this level the key points are phrase agreement, the plural, manner, and verbs that require the comitative.

Genitive + <code>-ga</code>: <code>sõber → sõbra → sõbraga</code>
Plural genitive + <code>-ga</code>: <code>sõbrad → sõprade → sõpradega</code>
Adjectives stay in the genitive; only the noun takes <code>-ga</code>: <code>uue autoga</code>, <code>vanade sõpradega</code>
Verbs with the comitative: <code>rahul olema</code> (be satisfied with), <code>nõus olema</code> (agree with), <code>tegelema</code> (be engaged in), <code>kohtuma</code> (meet)

💬 <i>Ma sõitsin tööle uue autoga.</i> — I drove to work in the new car.
💬 <i>Ta tuli peole oma vanade sõpradega.</i> — She came to the party with her old friends.
💬 <i>Ta rääkis sellest suure rõõmuga.</i> — He talked about it with great joy.
💬 <i>Ma olen tulemusega väga rahul.</i> — I am very satisfied with the result.

⚠️ To join two people, use <code>ja</code> ("and"), not <code>-ga</code>: <i>Mari ja Jaan tulid.</i> And never put <code>-ga</code> on the adjective too: not <i>uuega autoga</i>.

💡 The <code>-ga</code> sits once, at the very end of the phrase, like a full stop.$c$ WHERE id = 'b2-comitative-case';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-comitative-case', 'en', $s$[{"text": "Hello. In this lesson we take the comitative case, <<kaasaütlev>>, to the next level.", "language": "en", "pause_after_ms": 900}, {"text": "Let's review. Add the ending <<ga>> to the genitive. <<sõber>> becomes <<sõbra>>, then <<sõbraga>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Here is the key rule at this level. The adjective does not take <<ga>>. It stays in the genitive, and the ending goes only on the noun.", "language": "en", "pause_after_ms": 1100}, {"text": "Ma sõitsin tööle uue autoga.", "language": "et", "pause_after_ms": 2400}, {"text": "I drove to work in the new car. The adjective <<uue>> stays in the genitive, and only <<autoga>> has the ending.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta tuli peole oma vanade sõpradega.", "language": "et", "pause_after_ms": 2400}, {"text": "She came to the party with her old friends. The plural works the same way: <<vanade sõpradega>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta rääkis sellest suure rõõmuga.", "language": "et", "pause_after_ms": 2400}, {"text": "He talked about it with great joy. Here the ending <<ga>> describes how something was done, just like English with.", "language": "en", "pause_after_ms": 1000}, {"text": "Some verbs always take the comitative. Learn them as fixed phrases.", "language": "en", "pause_after_ms": 900}, {"text": "Ma olen tulemusega väga rahul.", "language": "et", "pause_after_ms": 2400}, {"text": "I am very satisfied with the result. Just like English satisfied with, <<rahul olema>> takes the comitative.", "language": "en", "pause_after_ms": 1000}, {"text": "Ta tegeleb vabal ajal spordiga.", "language": "et", "pause_after_ms": 2400}, {"text": "He does sport in his free time. The verb <<tegelema>>, to be busy with, always takes <<ga>> too.", "language": "en", "pause_after_ms": 1000}, {"text": "Ma olen sinuga täiesti nõus.", "language": "et", "pause_after_ms": 2400}, {"text": "I completely agree with you. Just like English agree with you, Estonian says <<sinuga>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Here is a common mistake. To join two people with and, do not use <<ga>>. Use <<ja>>.", "language": "en", "pause_after_ms": 1100}, {"text": "Mari ja Jaan tulid.", "language": "et", "pause_after_ms": 2400}, {"text": "<<Mari>> and <<Jaan>> came. Here we use <<ja>>, not the ending <<ga>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Now you try. Say: I met a new colleague. How do you say it in Estonian?", "language": "en", "pause_after_ms": 3800}, {"text": "Ma kohtusin uue kolleegiga.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. English just says met someone, but <<kohtuma>> needs the comitative. The adjective <<uue>> stays in the genitive.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: <<ga>> attaches to the genitive, the adjective does not take it, and some verbs require this case.", "language": "en", "pause_after_ms": 1000}, {"text": "Practise these verbs in your own sentences. See you soon.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Advanced Clause Connectors (sidesõnad)</b>
You already know <code>ja, aga, sest, et, kui</code>. At this level you link ideas precisely: cause, concession, result, time and condition.

<code>kuna</code> — since, as (cause; can open the sentence)
<code>ehkki</code>, <code>olgugi et</code> — although (more formal than kuigi)
<code>mistõttu</code> — which is why
<code>niipea kui</code> — as soon as
<code>juhul kui</code> — if, in the event that

A comma always stands before a subordinating connector inside the sentence. If the subordinate clause comes first, the main-clause verb usually follows right after the comma.

💬 <i>Kuna sajab vihma, jääme täna koju.</i> — Since it is raining, we are staying home today.
💬 <i>Ehkki ta oli väsinud, töötas ta edasi.</i> — Although he was tired, he kept working.
💬 <i>Rong hilines, mistõttu jäin koosolekule hiljaks.</i> — The train was late, which is why I was late for the meeting.
💬 <i>Helista mulle, niipea kui koju jõuad.</i> — Call me as soon as you get home.

⚠️ In English you can start a sentence with "Because...". In Estonian a sentence cannot begin with <code>sest</code>; to put the cause first, use <code>kuna</code>.

💡 <code>kuna</code> opens the front door of the sentence, <code>sest</code> only the back door.$c$ WHERE id = 'b2-clause-connectors';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-clause-connectors', 'en', $s$[{"text": "Hello. Today we look at advanced connectors for cause, result, time, condition and contrast. They help you link your ideas much more clearly.", "language": "en", "pause_after_ms": 900}, {"text": "First, a rule. A comma comes before a subordinating connector inside the sentence. If the subordinate clause comes first, the main verb usually follows right after the comma.", "language": "en", "pause_after_ms": 1100}, {"text": "Kuna sajab vihma, jääme täna koju.", "language": "et", "pause_after_ms": 2400}, {"text": "Since it is raining, we are staying home today. <<kuna>> can open the sentence, and the verb <<jääme>> comes right after the comma.", "language": "en", "pause_after_ms": 1000}, {"text": "Ehkki ta oli väsinud, töötas ta edasi.", "language": "et", "pause_after_ms": 2400}, {"text": "Although he was tired, he kept working. <<ehkki>> means the same as <<kuigi>>, but it is a little more formal.", "language": "en", "pause_after_ms": 1000}, {"text": "Rong hilines, mistõttu jäin koosolekule hiljaks.", "language": "et", "pause_after_ms": 2400}, {"text": "The train was late, which is why I was late for the meeting. <<mistõttu>> gives the result of what came before.", "language": "en", "pause_after_ms": 1000}, {"text": "Helista mulle, niipea kui koju jõuad.", "language": "et", "pause_after_ms": 2400}, {"text": "Call me as soon as you get home. <<niipea kui>> means as soon as.", "language": "en", "pause_after_ms": 1000}, {"text": "Helista mulle, juhul kui rong hilineb.", "language": "et", "pause_after_ms": 2400}, {"text": "Call me in case the train is late. <<juhul kui>> expresses a condition, like if or in case.", "language": "en", "pause_after_ms": 1000}, {"text": "Here is a common mistake. In English you can start a sentence with because. In Estonian a sentence cannot start with <<sest>>. Use <<kuna>> at the start.", "language": "en", "pause_after_ms": 1100}, {"text": "Now you try. Say: Since he was ill, he did not come to work. Put the cause first.", "language": "en", "pause_after_ms": 3800}, {"text": "Kuna ta oli haige, ei tulnud ta tööle.", "language": "et", "pause_after_ms": 2400}, {"text": "Correct. We started with <<kuna>>, and after the comma the negative verb <<ei tulnud>> came before the subject.", "language": "en", "pause_after_ms": 1000}, {"text": "To sum up: <<kuna>> for cause, <<ehkki>> for although, <<mistõttu>> for result, <<niipea kui>> for time, and <<juhul kui>> for condition.", "language": "en", "pause_after_ms": 1100}, {"text": "These connectors make your Estonian flow. See you in the next lesson.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Complex Verb Chains</b>

Estonian can stack three or more verbs. The key rule: each verb decides the form of the verb right after it, not the first verb of the chain.

<code>pidama, hakkama, jääma, õppima, minema + -ma</code>
<code>tahtma, võima, oskama, proovima, unustama, tohtima + -da</code>
<code>lakkama, loobuma + -mast</code>
<code>nägema, kuulma, leidma + object + -mas</code>

💬 <i>Ma pean hakkama rohkem sporti tegema.</i> — I have to start doing more sport.
💬 <i>Ta tahab õppida autot juhtima.</i> — She wants to learn to drive a car.
💬 <i>Ta lakkas eelmisel aastal suitsetamast.</i> — He stopped smoking last year.
💬 <i>Ma nägin teda pargis jooksmas.</i> — I saw him running in the park.

⚠️ Not every modal takes <code>-da</code>: <i>pidama</i> takes <code>-ma</code>. Say <i>Ma pean minema</i>, not <i>Ma pean minna</i>. The same verb also changes form inside a chain: <i>Ma tahan hakata õppima</i> (hakkama → hakata after tahtma).

💡 English uses "to" almost everywhere, so it will not tell you the form. Anchors: <code>-ma</code> after starting and having to (<i>hakkama õppima</i> ≈ start studying), <code>-mast</code> ≈ "from doing" (<i>loobuma suitsetamast</i> ≈ give up smoking), <code>-mas</code> ≈ "-ing" after see and hear.$c$ WHERE id = 'b2-verb-chains';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-verb-chains', 'en', $s$[{"text": "In this lesson we move on to an advanced topic: verb chains. In Estonian three verbs can stand in a row, and the form of each one matters.", "language": "en", "pause_after_ms": 1000}, {"text": "The key rule: each verb decides the form of the verb right after it. Is it the <<ma>> form or the <<da>> form?", "language": "en", "pause_after_ms": 1000}, {"text": "<<pidama>>, <<hakkama>>, <<jääma>> and <<õppima>> are followed by the <<ma>> infinitive.", "language": "en", "pause_after_ms": 900}, {"text": "Ma pean hakkama rohkem sporti tegema.", "language": "et", "pause_after_ms": 2400}, {"text": "I have to start doing more sport. <<pean>> calls for <<hakkama>>, and <<hakkama>> calls for <<tegema>>.", "language": "en", "pause_after_ms": 1000}, {"text": "<<tahtma>>, <<võima>>, <<oskama>>, <<unustama>> and <<tohtima>> are followed by the <<da>> infinitive.", "language": "en", "pause_after_ms": 900}, {"text": "Ta tahab õppida autot juhtima.", "language": "et", "pause_after_ms": 2400}, {"text": "She wants to learn to drive a car. After <<tahab>> comes <<õppida>>, but <<õppima>> itself calls for <<juhtima>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Sa ei tohiks unustada ust lukustada.", "language": "et", "pause_after_ms": 2400}, {"text": "You should not forget to lock the door. Here there are two <<da>> infinitives in a row.", "language": "en", "pause_after_ms": 1000}, {"text": "<<lakkama>> and <<loobuma>>, meaning to stop and to give up, take the <<mast>> form.", "language": "en", "pause_after_ms": 900}, {"text": "Ta lakkas eelmisel aastal suitsetamast.", "language": "et", "pause_after_ms": 2400}, {"text": "He stopped smoking last year. Think of the <<mast>> form as from doing: moving away from an activity.", "language": "en", "pause_after_ms": 1000}, {"text": "After verbs of seeing and hearing, you get an object and the <<mas>> form.", "language": "en", "pause_after_ms": 800}, {"text": "Ma nägin teda pargis jooksmas.", "language": "et", "pause_after_ms": 2400}, {"text": "I saw him running in the park. <<jooksmas>> shows an action going on at that moment, much like English running.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is to think every modal verb takes <<da>>. <<pidama>> always takes <<ma>>.", "language": "en", "pause_after_ms": 900}, {"text": "Ma pean minema.", "language": "et", "pause_after_ms": 2200}, {"text": "I have to go. Saying <<ma pean minna>> is wrong.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. Translate into Estonian: I want to start studying.", "language": "en", "pause_after_ms": 3800}, {"text": "Ma tahan hakata õppima.", "language": "et", "pause_after_ms": 2400}, {"text": "After <<tahtma>>, <<hakkama>> becomes <<hakata>>, and <<hakkama>> then calls for <<õppima>>.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: read the chain from left to right, and each time ask the verb in front which form comes next.", "language": "en", "pause_after_ms": 1000}, {"text": "Learning these patterns will make your speech much more fluent. See you soon.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Quotative Mood — Advanced (kaudne kõneviis)</b>

The quotative shows that information comes from someone else and the speaker does not vouch for it. At B2 you need all of its forms, as used in news and formal reporting.

Present: ma-infinitive stem + <code>-vat</code> → <code>tulema → tulevat</code>, <code>tegema → tegevat</code> (same for all persons)
Past: <code>olevat + -nud</code> → <code>olevat teinud</code>
Negative: <code>ei olevat</code>, <code>ei olevat teinud</code>
Passive past: <code>olevat + -tud</code> → <code>olevat tehtud</code>
"Is supposed to": <code>pidavat + -ma</code>

💬 <i>Ta olevat leidnud uue töö.</i> — He has reportedly found a new job.
💬 <i>Minister ei olevat sellest midagi teadnud.</i> — The minister reportedly knew nothing about it.
💬 <i>Vargad olevat kinni võetud.</i> — The thieves have reportedly been caught.
💬 <i>Küüslauk pidavat vererõhku alandama.</i> — Garlic is supposed to lower blood pressure.

⚠️ English "apparently" can also mark your own conclusion ("Apparently it snowed!" as you look outside). Estonian <code>-vat</code> is only for hearsay; for what you see yourself, say <i>Lund on sadanud!</i>

💡 In the news the quotative means "allegedly"; the adverb <i>väidetavalt</i> creates the same distance.$c$ WHERE id = 'b2-quotative-mood';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-quotative-mood', 'en', $s$[{"text": "Today we cover the advanced quotative mood. It shows that the information comes from someone else. English uses words like reportedly instead.", "language": "en", "pause_after_ms": 1000}, {"text": "For the present, add <<vat>> to the stem of the <<ma>> infinitive. <<tulema>> becomes <<tulevat>>, and <<tegema>> becomes <<tegevat>>. It never changes for person.", "language": "en", "pause_after_ms": 1000}, {"text": "Homme tulevat lund.", "language": "et", "pause_after_ms": 2200}, {"text": "Snow is reportedly coming tomorrow. We heard it in the forecast, and we are not vouching for it.", "language": "en", "pause_after_ms": 1000}, {"text": "For the past, use <<olevat>> together with the <<nud>> participle.", "language": "en", "pause_after_ms": 800}, {"text": "Ta olevat leidnud uue töö.", "language": "et", "pause_after_ms": 2400}, {"text": "He has reportedly found a new job. The participle of <<leidma>> is <<leidnud>>.", "language": "en", "pause_after_ms": 1000}, {"text": "In the negative, put <<ei>> in front, and the <<vat>> form stays the same.", "language": "en", "pause_after_ms": 800}, {"text": "Minister ei olevat sellest midagi teadnud.", "language": "et", "pause_after_ms": 2400}, {"text": "The minister reportedly knew nothing about it. This distanced style is very common in the news.", "language": "en", "pause_after_ms": 1000}, {"text": "For the passive past, combine <<olevat>> with the <<tud>> participle.", "language": "en", "pause_after_ms": 800}, {"text": "Vargad olevat kinni võetud.", "language": "et", "pause_after_ms": 2400}, {"text": "The thieves have reportedly been caught. We do not say who caught them. We only pass on what we heard.", "language": "en", "pause_after_ms": 1000}, {"text": "Finally, the form <<pidavat>> goes with the <<ma>> infinitive and means something is supposed to be true.", "language": "en", "pause_after_ms": 800}, {"text": "Küüslauk pidavat vererõhku alandama.", "language": "et", "pause_after_ms": 2400}, {"text": "Garlic is supposed to lower blood pressure. But this is a claim, not a proven fact.", "language": "en", "pause_after_ms": 1000}, {"text": "Careful: English apparently can also mark your own conclusion. Estonian never uses the quotative for something you see yourself.", "language": "en", "pause_after_ms": 900}, {"text": "Lund on sadanud!", "language": "et", "pause_after_ms": 2200}, {"text": "It has snowed! If you are looking out of the window yourself, you use the normal form.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. Use the quotative to say: I heard he did not go to work yesterday.", "language": "en", "pause_after_ms": 3800}, {"text": "Ta ei olevat eile tööl käinud.", "language": "et", "pause_after_ms": 2400}, {"text": "First <<ei olevat>>, then the participle <<käinud>>. That is the negative past quotative.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: <<vat>> for the present, <<olevat>> plus a participle for the past, and <<ei>> in front for the negative. None of them change for person.", "language": "en", "pause_after_ms": 1000}, {"text": "Next time you read Estonian news, look out for these forms. See you soon.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Word Formation Patterns</b>

Knowing a few suffixes lets you guess new words.

<code>-ja</code> doer: <code>õpetama → õpetaja</code>, <code>laulma → laulja</code>
<code>-mine</code> action: <code>ujuma → ujumine</code>
<code>-us</code> abstract noun: <code>sõber → sõprus</code>
<code>-tu</code> without: <code>maitse → maitsetu</code>
<code>-kas</code> having a lot of: <code>nali → naljakas</code> (funny)
<code>-la</code> place: <code>söök → söökla</code>, <code>haige → haigla</code>

Compounds: the first part is often in the genitive (<code>raamatu + kogu → raamatukogu</code>), but can also be in the nominative (<code>jalg + pall → jalgpall</code>). Only the last part is declined: <code>raamatukogus</code>.

💬 <i>Ujumine on tervisele kasulik.</i> — Swimming is good for your health.
💬 <i>Sõprus on tähtsam kui raha.</i> — Friendship is more important than money.
💬 <i>Supp oli täiesti maitsetu.</i> — The soup was completely tasteless.

⚠️ English often just puts two words side by side (bus stop); Estonian often puts the first part in the genitive: <i>bussipeatus</i>, not <i>busspeatus</i>.

💡 Many suffixes have an English twin: <code>-tu</code> ≈ -less (maitsetu ≈ tasteless), <code>-ja</code> ≈ -er (laulja ≈ singer), <code>-la</code> ≈ -ery as in "bakery" (söökla ≈ canteen).$c$ WHERE id = 'b2-word-formation';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-word-formation', 'en', $s$[{"text": "Today's topic will grow your vocabulary fast: word formation. Estonian builds dozens of words from a few roots with suffixes and compounds.", "language": "en", "pause_after_ms": 1000}, {"text": "First, the most common suffixes. <<ja>> names the doer, <<mine>> the action, <<us>> an abstract idea, and <<tu>> means without.", "language": "en", "pause_after_ms": 1000}, {"text": "Meie õpetaja on väga sõbralik.", "language": "et", "pause_after_ms": 2400}, {"text": "Our teacher is very friendly. <<õpetaja>> comes from <<õpetama>>, and <<sõbralik>> comes from <<sõber>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Ujumine on tervisele kasulik.", "language": "et", "pause_after_ms": 2400}, {"text": "Swimming is good for your health. The <<ma>> of <<ujuma>> drops off, and <<mine>> takes its place.", "language": "en", "pause_after_ms": 1000}, {"text": "Sõprus on tähtsam kui raha.", "language": "et", "pause_after_ms": 2400}, {"text": "Friendship is more important than money. With a consonant change, <<sõber>> gives <<sõprus>>.", "language": "en", "pause_after_ms": 1000}, {"text": "Supp oli täiesti maitsetu.", "language": "et", "pause_after_ms": 2400}, {"text": "The soup was completely tasteless. The ending <<tu>> means without, just like English less in tasteless.", "language": "en", "pause_after_ms": 1000}, {"text": "Now let's move on to compound words. In Estonian the first part is often in the genitive.", "language": "en", "pause_after_ms": 800}, {"text": "Raamatukogu on täna kinni.", "language": "et", "pause_after_ms": 2400}, {"text": "The library is closed today. <<raamat>> becomes <<raamatu>> in the genitive, and then <<kogu>> is added.", "language": "en", "pause_after_ms": 1000}, {"text": "Bussipeatus on maja ees.", "language": "et", "pause_after_ms": 2400}, {"text": "The bus stop is in front of the house. English just puts bus and stop side by side. Estonian marks the first part: <<bussi>> plus <<peatus>>.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is to leave the first part in its basic form. <<busspeatus>> is wrong, <<bussipeatus>> is right.", "language": "en", "pause_after_ms": 900}, {"text": "Your turn. <<laulma>> means to sing. Translate into Estonian: My mother is a singer.", "language": "en", "pause_after_ms": 3800}, {"text": "Minu ema on laulja.", "language": "et", "pause_after_ms": 2400}, {"text": "Drop the <<ma>> from <<laulma>>, add <<ja>>, and you get <<laulja>>, just like sing and singer.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: suffixes add new meanings, in compounds the first part is usually in the genitive, and only the last part is declined.", "language": "en", "pause_after_ms": 1000}, {"text": "When you see a new word, try breaking it into parts. See you soon.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
UPDATE grammar_lessons SET content = $c$<b>Stylistic Word Order Variations</b>

Estonian word order is flexible but not random. In neutral main clauses the finite verb stays in second place, and new or important information tends to come at the end.

<code>Mari läks eile tööle.</code> → neutral
<code>Eile läks Mari tööle.</code> → time first, verb still second, subject after the verb
<code>Raamat on laual.</code> (a known book) vs <code>Laual on raamat.</code> (a new book)
In subordinate clauses the verb often moves to the end.

💬 <i>Eile läks Mari varakult tööle.</i> — Yesterday Mari went to work early.
💬 <i>Seda raamatut olen ma juba lugenud.</i> — This book I have already read.
💬 <i>Ma tean, et ta homme Tartusse sõidab.</i> — I know that she is going to Tartu tomorrow.
💬 <i>Kui ma koju jõudsin, oli õhtusöök valmis.</i> — When I got home, dinner was ready.

⚠️ English keeps the subject before the verb even after a time word ("Yesterday Mari went"). Estonian does not: whatever comes first, the verb comes second: <i>Eile läks Mari...</i> A verb at the end, as in <i>Eile Mari varakult tööle läks</i>, is wrong in a main clause.

💡 Existential sentences put the place first and the new thing last: <i>Laual on raamat</i> ≈ "On the table there is a book". In casual speech you will also hear <i>Eile ma läksin...</i>, but in writing the inverted order is the safe choice.$c$ WHERE id = 'b2-word-order-advanced';
INSERT INTO grammar_lesson_podcasts (lesson_id, language, script, script_updated_at) VALUES ('b2-word-order-advanced', 'en', $s$[{"text": "In this lesson we go beyond basic word order. We will see how moving words around changes the emphasis.", "language": "en", "pause_after_ms": 1000}, {"text": "First rule: in a main clause the finite verb usually stands in second place. If a time or a place comes first, the verb still stays second.", "language": "en", "pause_after_ms": 1000}, {"text": "Mari läks eile varakult tööle.", "language": "et", "pause_after_ms": 2400}, {"text": "<<Mari>> went to work early yesterday. This is the neutral order: subject first, verb second.", "language": "en", "pause_after_ms": 1000}, {"text": "Eile läks Mari varakult tööle.", "language": "et", "pause_after_ms": 2400}, {"text": "Yesterday <<Mari>> went to work early. The time moved to the front, the verb is still second, and the subject comes after the verb.", "language": "en", "pause_after_ms": 1000}, {"text": "Second rule: new or important information usually goes to the end of the sentence. Compare these two sentences.", "language": "en", "pause_after_ms": 900}, {"text": "Raamat on laual.", "language": "et", "pause_after_ms": 2200}, {"text": "The book is on the table. We already know the book. The new information is where it is.", "language": "en", "pause_after_ms": 1000}, {"text": "Laual on uus raamat.", "language": "et", "pause_after_ms": 2200}, {"text": "There is a new book on the table. This time the new information is the book, so it goes last.", "language": "en", "pause_after_ms": 1000}, {"text": "Seda raamatut olen ma juba lugenud.", "language": "et", "pause_after_ms": 2400}, {"text": "This book I have already read. Putting the object first gives it emphasis, and the verb is still second.", "language": "en", "pause_after_ms": 1000}, {"text": "In subordinate clauses, the verb often moves to the end.", "language": "en", "pause_after_ms": 800}, {"text": "Ma tean, et ta homme Tartusse sõidab.", "language": "et", "pause_after_ms": 2400}, {"text": "I know that she is going to <<Tartu>> tomorrow. In the clause starting with <<et>>, <<sõidab>> moved to the end.", "language": "en", "pause_after_ms": 1000}, {"text": "A common mistake is to keep English order, subject then verb, after a time word or a clause. Even when a subordinate clause comes first, the main verb stays second.", "language": "en", "pause_after_ms": 800}, {"text": "Kui ma koju jõudsin, oli õhtusöök valmis.", "language": "et", "pause_after_ms": 2400}, {"text": "When I got home, dinner was ready. The subordinate clause took first place, so <<oli>> comes right after it.", "language": "en", "pause_after_ms": 1000}, {"text": "Your turn. Put the time first and translate: Tomorrow <<Peeter>> is going to the capital.", "language": "en", "pause_after_ms": 3800}, {"text": "Homme sõidab Peeter pealinna.", "language": "et", "pause_after_ms": 2400}, {"text": "<<homme>> comes first, the verb <<sõidab>> is second, and the subject <<Peeter>> comes after the verb.", "language": "en", "pause_after_ms": 900}, {"text": "To sum up: in a main clause the verb stays second, new information goes last, and in a subordinate clause the verb can move to the end.", "language": "en", "pause_after_ms": 1000}, {"text": "Try to notice this order in the texts you read. See you soon.", "language": "en", "pause_after_ms": 800}]$s$::jsonb, NOW()) ON CONFLICT (lesson_id, language) DO UPDATE SET script = EXCLUDED.script, script_updated_at = NOW();
